INSERT INTO system_vocabulary_words (id, set_id, topic_id, part_id, word, ipa, cefr, part_of_speech, meaning_vi, definition_en, example_en, example_vi, example_toeic, audio_us, audio_uk, image_url, synonyms, antonyms, phrases, confusables, word_family, audio_voices, note_vi, toeic_topic, difficulty_level, order_index) VALUES
('5b9278e8-6ed4-5383-bbe7-e2d3d68f8617', '9adb6452-11a5-5b18-bb10-e71549f348f5', '0f4c22df-e7c4-5178-a8a4-f5b8f5f32a3d', '2e9c2d31-84bb-5fde-8b38-3a72d1ec3281', 'telephone', '/ˈtelɪfəʊn/', 'A1', 'noun', 'Thiết bị dùng để liên lạc bằng giọng nói từ xa.', 'a system or device used for talking to someone who is in another place.', 'Could you please answer the telephone? It\'s been ringing for a while.', 'Bạn có thể nghe điện thoại được không? Nó đã reo một lúc rồi.', '{\"en\": \"Please leave a message on the office telephone if no one answers your call today.\", \"vi\": \"Vui lòng để lại tin nhắn trên điện thoại văn phòng nếu không ai trả lời cuộc gọi của bạn hôm nay.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/telephone-ljspeech-3b01d3eb.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/telephone-cori-3b01d3eb.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/telephone-1a0b2343.webp', '[\"phone\", \"handset\"]', NULL, '[{\"phrase\": \"answer the telephone\", \"meaning\": \"trả lời điện thoại\"}, {\"phrase\": \"make a telephone call\", \"meaning\": \"thực hiện cuộc gọi\"}]', '[{\"word\": \"mobile\", \"note_vi\": \"mobile là điện thoại di động, telephone thường chỉ máy bàn.\"}]', '[{\"pos\": \"noun\", \"word\": \"telephony\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/telephone-cori-3b01d3eb.mp3\", \"/storage/v1/object/public/pronunciation/v2/telephone-aru0-3b01d3eb.mp3\", \"/storage/v1/object/public/pronunciation/v2/telephone-aru5-3b01d3eb.mp3\", \"/storage/v1/object/public/pronunciation/v2/telephone-aru6-3b01d3eb.mp3\", \"/storage/v1/object/public/pronunciation/v2/telephone-aru10-3b01d3eb.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/telephone-aru9-3b01d3eb.mp3\", \"/storage/v1/object/public/pronunciation/v2/telephone-aru3-3b01d3eb.mp3\", \"/storage/v1/object/public/pronunciation/v2/telephone-aru7-3b01d3eb.mp3\", \"/storage/v1/object/public/pronunciation/v2/telephone-aru8-3b01d3eb.mp3\", \"/storage/v1/object/public/pronunciation/v2/telephone-aru2-3b01d3eb.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/telephone-ljspeech-3b01d3eb.mp3\", \"/storage/v1/object/public/pronunciation/v2/telephone-lt408-3b01d3eb.mp3\", \"/storage/v1/object/public/pronunciation/v2/telephone-lt138-3b01d3eb.mp3\", \"/storage/v1/object/public/pronunciation/v2/telephone-lt624-3b01d3eb.mp3\", \"/storage/v1/object/public/pronunciation/v2/telephone-lt396-3b01d3eb.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/telephone-lt498-3b01d3eb.mp3\", \"/storage/v1/object/public/pronunciation/v2/telephone-lt132-3b01d3eb.mp3\", \"/storage/v1/object/public/pronunciation/v2/telephone-lt288-3b01d3eb.mp3\", \"/storage/v1/object/public/pronunciation/v2/telephone-lt42-3b01d3eb.mp3\", \"/storage/v1/object/public/pronunciation/v2/telephone-lt90-3b01d3eb.mp3\"]}}', 'Trong công sở, \'telephone\' thường chỉ điện thoại bàn cố định.', 'office', 1, 0),
('29678520-b84d-5d92-b614-9b16fa47c823', '9adb6452-11a5-5b18-bb10-e71549f348f5', '0f4c22df-e7c4-5178-a8a4-f5b8f5f32a3d', '2e9c2d31-84bb-5fde-8b38-3a72d1ec3281', 'hundred', '/ˈhʌndrəd/', 'A1', 'noun', 'Số một trăm (100).', 'the number that is equal to ten times ten.', 'There were over one hundred people at the concert.', 'Có hơn một trăm người tại buổi hòa nhạc.', '{\"en\": \"The company ordered one hundred new office chairs for the renovated headquarters.\", \"vi\": \"Công ty đã đặt mua một trăm chiếc ghế văn phòng mới cho trụ sở mới cải tạo.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/hundred-ljspeech-e9b039ad.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/hundred-cori-e9b039ad.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/hundred-8f993167.webp', NULL, NULL, '[{\"phrase\": \"a hundred percent\", \"meaning\": \"một trăm phần trăm (hoàn toàn)\"}, {\"phrase\": \"several hundred\", \"meaning\": \"vài trăm\"}]', '[{\"word\": \"thousand\", \"note_vi\": \"nghĩa là một nghìn, tránh nhầm với một trăm\"}]', '[{\"pos\": \"adjective\", \"word\": \"hundredth\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/hundred-cori-e9b039ad.mp3\", \"/storage/v1/object/public/pronunciation/v2/hundred-aru0-e9b039ad.mp3\", \"/storage/v1/object/public/pronunciation/v2/hundred-aru5-e9b039ad.mp3\", \"/storage/v1/object/public/pronunciation/v2/hundred-aru6-e9b039ad.mp3\", \"/storage/v1/object/public/pronunciation/v2/hundred-aru10-e9b039ad.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/hundred-aru9-e9b039ad.mp3\", \"/storage/v1/object/public/pronunciation/v2/hundred-aru3-e9b039ad.mp3\", \"/storage/v1/object/public/pronunciation/v2/hundred-aru7-e9b039ad.mp3\", \"/storage/v1/object/public/pronunciation/v2/hundred-aru8-e9b039ad.mp3\", \"/storage/v1/object/public/pronunciation/v2/hundred-aru2-e9b039ad.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/hundred-ljspeech-e9b039ad.mp3\", \"/storage/v1/object/public/pronunciation/v2/hundred-lt408-e9b039ad.mp3\", \"/storage/v1/object/public/pronunciation/v2/hundred-lt138-e9b039ad.mp3\", \"/storage/v1/object/public/pronunciation/v2/hundred-lt624-e9b039ad.mp3\", \"/storage/v1/object/public/pronunciation/v2/hundred-lt396-e9b039ad.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/hundred-lt498-e9b039ad.mp3\", \"/storage/v1/object/public/pronunciation/v2/hundred-lt132-e9b039ad.mp3\", \"/storage/v1/object/public/pronunciation/v2/hundred-lt288-e9b039ad.mp3\", \"/storage/v1/object/public/pronunciation/v2/hundred-lt42-e9b039ad.mp3\", \"/storage/v1/object/public/pronunciation/v2/hundred-lt90-e9b039ad.mp3\"]}}', 'Tránh nhầm lẫn cách viết giữa hundred (trăm) và hungry (đói).', 'finance', 1, 1),
('80d9e234-184c-5961-ad50-ca77520d12f1', '9adb6452-11a5-5b18-bb10-e71549f348f5', '0f4c22df-e7c4-5178-a8a4-f5b8f5f32a3d', '2e9c2d31-84bb-5fde-8b38-3a72d1ec3281', 'rain', '/reɪn/', 'A1', 'noun', 'nước rơi từ mây xuống đất dưới dạng giọt.', 'water that falls from clouds in small drops towards the ground.', 'The heavy rain caused some flooding in the streets.', 'Cơn mưa lớn đã gây ra một số trận lụt trên các con phố.', '{\"en\": \"Heavy rain delayed the outdoor corporate event by at least two hours yesterday.\", \"vi\": \"Mưa lớn đã làm trì hoãn sự kiện ngoài trời của công ty ít nhất hai giờ vào ngày hôm qua.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/rain-ljspeech-fbec17cb.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/rain-cori-fbec17cb.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/rain-2d6a44e9.webp', '[\"rainfall\", \"precipitation\"]', '[\"drought\"]', '[{\"phrase\": \"heavy rain\", \"meaning\": \"mưa lớn\"}, {\"phrase\": \"torrential rain\", \"meaning\": \"mưa như trút nước\"}]', '[{\"word\": \"reign\", \"note_vi\": \"reign nghĩa là triều đại hoặc trị vì, phát âm giống rain.\"}, {\"word\": \"rein\", \"note_vi\": \"rein nghĩa là dây cương điều khiển ngựa.\"}]', '[{\"pos\": \"verb\", \"word\": \"rain\"}, {\"pos\": \"adjective\", \"word\": \"rainy\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/rain-cori-fbec17cb.mp3\", \"/storage/v1/object/public/pronunciation/v2/rain-aru0-fbec17cb.mp3\", \"/storage/v1/object/public/pronunciation/v2/rain-aru5-fbec17cb.mp3\", \"/storage/v1/object/public/pronunciation/v2/rain-aru6-fbec17cb.mp3\", \"/storage/v1/object/public/pronunciation/v2/rain-aru10-fbec17cb.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/rain-aru9-fbec17cb.mp3\", \"/storage/v1/object/public/pronunciation/v2/rain-aru3-fbec17cb.mp3\", \"/storage/v1/object/public/pronunciation/v2/rain-aru7-fbec17cb.mp3\", \"/storage/v1/object/public/pronunciation/v2/rain-aru8-fbec17cb.mp3\", \"/storage/v1/object/public/pronunciation/v2/rain-aru2-fbec17cb.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/rain-ljspeech-fbec17cb.mp3\", \"/storage/v1/object/public/pronunciation/v2/rain-lt408-fbec17cb.mp3\", \"/storage/v1/object/public/pronunciation/v2/rain-lt138-fbec17cb.mp3\", \"/storage/v1/object/public/pronunciation/v2/rain-lt624-fbec17cb.mp3\", \"/storage/v1/object/public/pronunciation/v2/rain-lt396-fbec17cb.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/rain-lt498-fbec17cb.mp3\", \"/storage/v1/object/public/pronunciation/v2/rain-lt132-fbec17cb.mp3\", \"/storage/v1/object/public/pronunciation/v2/rain-lt288-fbec17cb.mp3\", \"/storage/v1/object/public/pronunciation/v2/rain-lt42-fbec17cb.mp3\", \"/storage/v1/object/public/pronunciation/v2/rain-lt90-fbec17cb.mp3\"]}}', 'Rain vừa là danh từ (cơn mưa) vừa là động từ (trời mưa).', 'nature', 1, 2),
('f8e0b916-35b2-5e11-85e1-b263644ec2a9', '9adb6452-11a5-5b18-bb10-e71549f348f5', '0f4c22df-e7c4-5178-a8a4-f5b8f5f32a3d', '2e9c2d31-84bb-5fde-8b38-3a72d1ec3281', 'imagine', '/ɪˈmædʒɪn/', 'A2', 'verb', 'Tạo ra hình ảnh hoặc ý tưởng trong tâm trí.', 'to form a picture or idea in your mind about what something could be like.', 'Can you imagine a world without smartphones? It\'s hard to picture now.', 'Bạn có thể tưởng tượng một thế giới không có điện thoại thông minh không? Bây giờ thật khó hình dung.', '{\"en\": \"It is hard to imagine how the new marketing strategy will affect our sales this quarter.\", \"vi\": \"Thật khó để hình dung chiến lược tiếp thị mới sẽ ảnh hưởng đến doanh số quý này ra sao.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/imagine-ljspeech-971687e3.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/imagine-cori-971687e3.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/imagine-ae3b1a58.webp', '[\"visualize\", \"envision\", \"picture\"]', NULL, '[{\"phrase\": \"hard to imagine\", \"meaning\": \"khó tưởng tượng\"}, {\"phrase\": \"imagine a scenario\", \"meaning\": \"hình dung một kịch bản\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"imagination\"}, {\"pos\": \"adjective\", \"word\": \"imaginative\"}, {\"pos\": \"adjective\", \"word\": \"imaginary\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/imagine-cori-971687e3.mp3\", \"/storage/v1/object/public/pronunciation/v2/imagine-aru0-971687e3.mp3\", \"/storage/v1/object/public/pronunciation/v2/imagine-aru5-971687e3.mp3\", \"/storage/v1/object/public/pronunciation/v2/imagine-aru6-971687e3.mp3\", \"/storage/v1/object/public/pronunciation/v2/imagine-aru10-971687e3.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/imagine-aru9-971687e3.mp3\", \"/storage/v1/object/public/pronunciation/v2/imagine-aru3-971687e3.mp3\", \"/storage/v1/object/public/pronunciation/v2/imagine-aru7-971687e3.mp3\", \"/storage/v1/object/public/pronunciation/v2/imagine-aru8-971687e3.mp3\", \"/storage/v1/object/public/pronunciation/v2/imagine-aru2-971687e3.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/imagine-ljspeech-971687e3.mp3\", \"/storage/v1/object/public/pronunciation/v2/imagine-lt408-971687e3.mp3\", \"/storage/v1/object/public/pronunciation/v2/imagine-lt138-971687e3.mp3\", \"/storage/v1/object/public/pronunciation/v2/imagine-lt624-971687e3.mp3\", \"/storage/v1/object/public/pronunciation/v2/imagine-lt396-971687e3.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/imagine-lt498-971687e3.mp3\", \"/storage/v1/object/public/pronunciation/v2/imagine-lt132-971687e3.mp3\", \"/storage/v1/object/public/pronunciation/v2/imagine-lt288-971687e3.mp3\", \"/storage/v1/object/public/pronunciation/v2/imagine-lt42-971687e3.mp3\", \"/storage/v1/object/public/pronunciation/v2/imagine-lt90-971687e3.mp3\"]}}', 'Imagine thường đi với V-ing (tưởng tượng việc làm gì đó), không dùng với to V.', 'business', 1, 3),
('be7a43dc-08ec-5c8c-b31b-df063883f7d4', '9adb6452-11a5-5b18-bb10-e71549f348f5', '0f4c22df-e7c4-5178-a8a4-f5b8f5f32a3d', '2e9c2d31-84bb-5fde-8b38-3a72d1ec3281', 'hair', '/heə(r)/', 'A1', 'noun', 'Tóc trên đầu hoặc lông trên cơ thể.', 'the mass of thin thread-like structures that grow on the head of a person.', 'She has long, beautiful black hair.', 'Cô ấy có mái tóc đen dài, rất đẹp.', '{\"en\": \"Employees in the food processing area must wear a net to cover their hair.\", \"vi\": \"Nhân viên trong khu vực chế biến thực phẩm phải đội lưới để che tóc.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/hair-ljspeech-bc70b051.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/hair-cori-bc70b051.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/hair-ac0529f0.webp', NULL, NULL, '[{\"phrase\": \"blonde hair\", \"meaning\": \"tóc vàng\"}, {\"phrase\": \"curly hair\", \"meaning\": \"tóc xoăn\"}, {\"phrase\": \"hair salon\", \"meaning\": \"tiệm làm tóc\"}]', '[{\"word\": \"hare\", \"note_vi\": \"thỏ rừng, phát âm giống hệt hair\"}]', '[{\"pos\": \"adjective\", \"word\": \"hairy\"}, {\"pos\": \"adjective\", \"word\": \"hairless\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/hair-cori-bc70b051.mp3\", \"/storage/v1/object/public/pronunciation/v2/hair-aru0-bc70b051.mp3\", \"/storage/v1/object/public/pronunciation/v2/hair-aru5-bc70b051.mp3\", \"/storage/v1/object/public/pronunciation/v2/hair-aru6-bc70b051.mp3\", \"/storage/v1/object/public/pronunciation/v2/hair-aru10-bc70b051.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/hair-aru9-bc70b051.mp3\", \"/storage/v1/object/public/pronunciation/v2/hair-aru3-bc70b051.mp3\", \"/storage/v1/object/public/pronunciation/v2/hair-aru7-bc70b051.mp3\", \"/storage/v1/object/public/pronunciation/v2/hair-aru8-bc70b051.mp3\", \"/storage/v1/object/public/pronunciation/v2/hair-aru2-bc70b051.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/hair-ljspeech-bc70b051.mp3\", \"/storage/v1/object/public/pronunciation/v2/hair-lt408-bc70b051.mp3\", \"/storage/v1/object/public/pronunciation/v2/hair-lt138-bc70b051.mp3\", \"/storage/v1/object/public/pronunciation/v2/hair-lt624-bc70b051.mp3\", \"/storage/v1/object/public/pronunciation/v2/hair-lt396-bc70b051.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/hair-lt498-bc70b051.mp3\", \"/storage/v1/object/public/pronunciation/v2/hair-lt132-bc70b051.mp3\", \"/storage/v1/object/public/pronunciation/v2/hair-lt288-bc70b051.mp3\", \"/storage/v1/object/public/pronunciation/v2/hair-lt42-bc70b051.mp3\", \"/storage/v1/object/public/pronunciation/v2/hair-lt90-bc70b051.mp3\"]}}', 'Hair thường là danh từ không đếm được khi chỉ mái tóc, nhưng đếm được khi chỉ từng sợi tóc.', 'daily', 1, 4),
('cfefc6ec-71eb-53dd-b360-717a8ed02fd6', '9adb6452-11a5-5b18-bb10-e71549f348f5', '0f4c22df-e7c4-5178-a8a4-f5b8f5f32a3d', '2e9c2d31-84bb-5fde-8b38-3a72d1ec3281', 'chair', '/tʃeə(r)/', 'A1', 'noun', 'Đồ nội thất có lưng tựa và bốn chân, dùng để ngồi.', 'a piece of furniture with a back used for sitting.', 'The manager adjusted the ergonomic office chair to support his back during long meetings.', 'Quản lý đã điều chỉnh chiếc ghế văn phòng công thái học để hỗ trợ lưng của mình trong các cuộc họp kéo dài.', '{\"en\": \"The client sat on the chair during the office meeting.\", \"vi\": \"Khách hàng ngồi trên ghế tựa trong cuộc họp văn phòng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/chair-ljspeech-851e13a6.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/chair-cori-851e13a6.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/chair-c9090cf0.webp', '[\"seat\", \"armchair\"]', NULL, '[{\"phrase\": \"office chair\", \"meaning\": \"ghế văn phòng\"}, {\"phrase\": \"sit on a chair\", \"meaning\": \"ngồi trên ghế\"}, {\"phrase\": \"chairperson\", \"meaning\": \"người chủ tọa\"}]', '[{\"word\": \"cheer\", \"note_vi\": \"cheer nghĩa là cổ vũ, không phải ghế.\"}]', '[{\"pos\": \"verb\", \"word\": \"chair\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/chair-cori-851e13a6.mp3\", \"/storage/v1/object/public/pronunciation/v2/chair-aru0-851e13a6.mp3\", \"/storage/v1/object/public/pronunciation/v2/chair-aru5-851e13a6.mp3\", \"/storage/v1/object/public/pronunciation/v2/chair-aru6-851e13a6.mp3\", \"/storage/v1/object/public/pronunciation/v2/chair-aru10-851e13a6.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/chair-aru9-851e13a6.mp3\", \"/storage/v1/object/public/pronunciation/v2/chair-aru3-851e13a6.mp3\", \"/storage/v1/object/public/pronunciation/v2/chair-aru7-851e13a6.mp3\", \"/storage/v1/object/public/pronunciation/v2/chair-aru8-851e13a6.mp3\", \"/storage/v1/object/public/pronunciation/v2/chair-aru2