('9427a99b-396f-57a9-9866-e15fd4a80f14', '9adb6452-11a5-5b18-bb10-e71549f348f5', '1fff6119-8348-5cea-8b33-1f04e28f418d', 'd9f64193-17b6-51aa-ae34-18a0b684652a', 'battery', 'UK: /ˈbætəri/ | US: /ˈbætəri/', 'A2', 'noun', 'pin', 'a portable device that stores electrical energy and provides power to electronic equipment.', 'My phone battery needs to be charged soon.', 'Pin điện thoại của tôi cần được sạc sớm.', '{\"en\": \"The new smartphone model features an extended battery life that lasts up to 48 hours.\", \"vi\": \"Mẫu điện thoại thông minh mới sở hữu thời lượng pin kéo dài lên đến 48 giờ.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/battery-ljspeech-3f3c58ae.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/battery-cori-3f3c58ae.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/battery-30d2d596.webp', '[\"power cell\", \"accumulator\"]', NULL, '[{\"phrase\": \"battery life\", \"meaning\": \"thời lượng pin\"}, {\"phrase\": \"rechargeable battery\", \"meaning\": \"pin sạc lại được\"}, {\"phrase\": \"low battery\", \"meaning\": \"pin yếu\"}]', '[{\"word\": \"bakery\", \"note_vi\": \"tiệm bánh\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/battery-cori-3f3c58ae.mp3\", \"/storage/v1/object/public/pronunciation/v2/battery-aru0-3f3c58ae.mp3\", \"/storage/v1/object/public/pronunciation/v2/battery-aru5-3f3c58ae.mp3\", \"/storage/v1/object/public/pronunciation/v2/battery-aru6-3f3c58ae.mp3\", \"/storage/v1/object/public/pronunciation/v2/battery-aru10-3f3c58ae.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/battery-aru9-3f3c58ae.mp3\", \"/storage/v1/object/public/pronunciation/v2/battery-aru3-3f3c58ae.mp3\", \"/storage/v1/object/public/pronunciation/v2/battery-aru7-3f3c58ae.mp3\", \"/storage/v1/object/public/pronunciation/v2/battery-aru8-3f3c58ae.mp3\", \"/storage/v1/object/public/pronunciation/v2/battery-aru2-3f3c58ae.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronuncia