('e6467962-dc05-5a8e-887d-ec12bf99fd2e', '9adb6452-11a5-5b18-bb10-e71549f348f5', '2b83b85f-5b51-5624-a164-1f201372948e', '08711558-a5d6-5ba6-ac0f-c2c619160b0e', 'letter', '/ˈletə(r)/', 'A1', 'noun', 'tin nhắn viết trên giấy gửi cho ai đó.', 'a written message sent by post or delivered to someone in an envelope.', 'I received a letter from my friend who lives abroad.', 'Tôi đã nhận được một lá thư từ người bạn sống ở nước ngoài của mình.', '{\"en\": \"The manager sent a formal letter to the client regarding the new service contract.\", \"vi\": \"Giám đốc đã gửi một lá thư chính thức cho khách hàng về hợp đồng dịch vụ mới.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/letter-ljspeech-18cc852c.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/letter-cori-18cc852c.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/letter-33661a01.webp', '[\"correspondence\", \"note\"]', NULL, '[{\"phrase\": \"write a letter\", \"meaning\": \"viết thư\"}, {\"phrase\": \"receive a letter\", \"meaning\": \"nhận thư\"}]', '[{\"word\": \"litter\", \"note_vi\": \"litter là rác thải, còn letter là lá thư.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/letter-cori-18cc852c.mp3\", \"/storage/v1/object/public/pronunciation/v2/letter-aru0-18cc852c.mp3\", \"/storage/v1/object/public/pronunciation/v2/letter-aru5-18cc852c.mp3\", \"/storage/v1/object/public/pronunciation/v2/letter-aru6-18cc852c.mp3\", \"/storage/v1/object/public/pronunciation/v2/letter-aru10-18cc852c.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/letter-aru9-18cc852c.mp3\", \"/storage/v1/object/public/pronunciation/v2/letter-aru3-18cc852c.mp3\", \"/storage/v1/object/public/pronunciation/v2/letter-aru7-18cc852c.mp3\", \"/storage/v1/object/public/pronunciation/v2/letter-aru8-18cc852c.mp3\", \"/storage/v1/object/public/pronunciation/v2/letter-aru2-18cc852c.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/letter-ljspeech-18