('7ca28206-2ab3-5567-b096-32159393f56e', '9adb6452-11a5-5b18-bb10-e71549f348f5', '2b83b85f-5b51-5624-a164-1f201372948e', '08711558-a5d6-5ba6-ac0f-c2c619160b0e', 'never', '/ˈnevə(r)/', 'A1', 'adverb', 'Không một lần nào, chưa từng.', 'not at any time or not on any occasion in the past or future.', 'I have never visited Hanoi, but I hope to someday.', 'Tôi chưa bao giờ đến thăm Hà Nội, nhưng tôi hy vọng sẽ đi vào một ngày nào đó.', '{\"en\": \"Employees should never share their computer passwords with anyone in the office.\", \"vi\": \"Nhân viên không bao giờ được chia sẻ mật khẩu máy tính của họ với bất kỳ ai trong văn phòng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/never-ljspeech-85777c03.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/never-cori-85777c03.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/never-79464b68.webp', '[\"rarely\", \"seldom\"]', '[\"always\", \"forever\"]', '[{\"phrase\": \"almost never\", \"meaning\": \"hầu như không bao giờ\"}, {\"phrase\": \"never mind\", \"meaning\": \"đừng bận tâm\"}]', '[{\"word\": \"ever\", \"note_vi\": \"ever dùng trong câu hỏi/phủ định, never mang nghĩa phủ định tuyệt đối\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/never-cori-85777c03.mp3\", \"/storage/v1/object/public/pronunciation/v2/never-aru0-85777c03.mp3\", \"/storage/v1/object/public/pronunciation/v2/never-aru5-85777c03.mp3\", \"/storage/v1/object/public/pronunciation/v2/never-aru6-85777c03.mp3\", \"/storage/v1/object/public/pronunciation/v2/never-aru10-85777c03.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/never-aru9-85777c03.mp3\", \"/storage/v1/object/public/pronunciation/v2/never-aru3-85777c03.mp3\", \"/storage/v1/object/public/pronunciation/v2/never-aru7-85777c03.mp3\", \"/storage/v1/object/public/pronunciation/v2/never-aru8-85777c03.mp3\", \"/storage/v1/object/public/pronunciation/v2/never-aru2-85777c03.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object