('4f051da8-d321-5c08-8793-80166d9e81c0', '9adb6452-11a5-5b18-bb10-e71549f348f5', '2bfdcce5-4c35-5973-aa68-4b27209afc4f', 'c6fafa29-2c29-5b01-8f0c-51d0c84da3f3', 'left', '/left/', 'A1', 'adjective', 'Thuộc về phía đối diện với bên phải.', 'located on or relating to the side of the body towards the west when facing north.', 'Turn left at the next traffic light to reach the post office.', 'Rẽ trái ở đèn giao thông tiếp theo để đến bưu điện.', '{\"en\": \"Please sign your signature on the bottom left side of this agreement document.\", \"vi\": \"Vui lòng ký tên của bạn ở phía dưới bên trái của văn bản hợp đồng này.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/left-ljspeech-12c0f1fb.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/left-cori-12c0f1fb.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/left-5f96473e.webp', NULL, '[\"right\"]', '[{\"phrase\": \"left side\", \"meaning\": \"phía bên trái\"}, {\"phrase\": \"left hand\", \"meaning\": \"tay trái\"}, {\"phrase\": \"left corner\", \"meaning\": \"góc bên trái\"}]', '[{\"word\": \"leave\", \"note_vi\": \"left còn là dạng quá khứ và quá khứ phân từ của động từ leave (rời đi).\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/left-cori-12c0f1fb.mp3\", \"/storage/v1/object/public/pronunciation/v2/left-aru0-12c0f1fb.mp3\", \"/storage/v1/object/public/pronunciation/v2/left-aru5-12c0f1fb.mp3\", \"/storage/v1/object/public/pronunciation/v2/left-aru6-12c0f1fb.mp3\", \"/storage/v1/object/public/pronunciation/v2/left-aru10-12c0f1fb.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/left-aru9-12c0f1fb.mp3\", \"/storage/v1/object/public/pronunciation/v2/left-aru3-12c0f1fb.mp3\", \"/storage/v1/object/public/pronunciation/v2/left-aru7-12c0f1fb.mp3\", \"/storage/v1/object/public/pronunciation/v2/left-aru8-12c0f1fb.mp3\", \"/storage/v1/object/public/pronunciation/v2/left-aru2-12c0f1fb.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronun