('abfb26ca-ac7a-51f7-b373-f4305fd6de91', '9adb6452-11a5-5b18-bb10-e71549f348f5', '2bfdcce5-4c35-5973-aa68-4b27209afc4f', 'c6fafa29-2c29-5b01-8f0c-51d0c84da3f3', 'daughter', '/ˈdɔːtə(r)/', 'A1', 'noun', 'Con ruột hoặc con nuôi là nữ giới của một người.', 'a female child considered in relation to her mother and father.', 'Their daughter just started university this semester.', 'Con gái của họ vừa mới bắt đầu học đại học kỳ này.', '{\"en\": \"Our employee took leave to care for her sick daughter.\", \"vi\": \"Nhân viên của chúng tôi đã xin nghỉ để chăm con gái ốm.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/daughter-ljspeech-6490e67e.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/daughter-cori-6490e67e.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/daughter-1bb59cd3.webp', NULL, '[\"son\"]', '[{\"phrase\": \"eldest daughter\", \"meaning\": \"con gái cả\"}, {\"phrase\": \"daughter company\", \"meaning\": \"công ty con\"}, {\"phrase\": \"daughter-in-law\", \"meaning\": \"con dâu\"}]', '[{\"word\": \"laughter\", \"note_vi\": \"laughter nghĩa là tiếng cười, không phải con gái.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/daughter-cori-6490e67e.mp3\", \"/storage/v1/object/public/pronunciation/v2/daughter-aru0-6490e67e.mp3\", \"/storage/v1/object/public/pronunciation/v2/daughter-aru5-6490e67e.mp3\", \"/storage/v1/object/public/pronunciation/v2/daughter-aru6-6490e67e.mp3\", \"/storage/v1/object/public/pronunciation/v2/daughter-aru10-6490e67e.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/daughter-aru9-6490e67e.mp3\", \"/storage/v1/object/public/pronunciation/v2/daughter-aru3-6490e67e.mp3\", \"/storage/v1/object/public/pronunciation/v2/daughter-aru7-6490e67e.mp3\", \"/storage/v1/object/public/pronunciation/v2/daughter-aru8-6490e67e.mp3\", \"/storage/v1/object/public/pronunciation/v2/daughter-aru2-6490e67e.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/