('17ab8d33-0409-5640-bf78-f393b6f8d1a5', '9adb6452-11a5-5b18-bb10-e71549f348f5', '3edbe970-dcad-536f-b4d5-f75fb28cab57', 'f3f4d34f-c03a-5dfc-b6b2-5cfc839a9dbe', 'swim', '/swɪm/', 'A2', 'verb', 'di chuyển trong nước bằng cách dùng tay và chân.', 'to move through water by moving your body parts like arms and legs.', 'I love to swim in the ocean during summer holidays.', 'Tôi thích bơi ở biển trong những kỳ nghỉ hè.', '{\"en\": \"Guests can swim in the hotel pool after checking in at the front desk today.\", \"vi\": \"Khách có thể bơi trong hồ bơi khách sạn sau khi làm thủ tục tại quầy lễ tân hôm nay.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/swim-ljspeech-b89f90f3.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/swim-cori-b89f90f3.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/swim-7b224293.webp', '[\"float\", \"dive\"]', NULL, '[{\"phrase\": \"go for a swim\", \"meaning\": \"đi bơi\"}, {\"phrase\": \"learn to swim\", \"meaning\": \"học bơi\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"swimmer\"}, {\"pos\": \"noun\", \"word\": \"swimming\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/swim-cori-b89f90f3.mp3\", \"/storage/v1/object/public/pronunciation/v2/swim-aru0-b89f90f3.mp3\", \"/storage/v1/object/public/pronunciation/v2/swim-aru5-b89f90f3.mp3\", \"/storage/v1/object/public/pronunciation/v2/swim-aru6-b89f90f3.mp3\", \"/storage/v1/object/public/pronunciation/v2/swim-aru10-b89f90f3.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/swim-aru9-b89f90f3.mp3\", \"/storage/v1/object/public/pronunciation/v2/swim-aru3-b89f90f3.mp3\", \"/storage/v1/object/public/pronunciation/v2/swim-aru7-b89f90f3.mp3\", \"/storage/v1/object/public/pronunciation/v2/swim-aru8-b89f90f3.mp3\", \"/storage/v1/object/public/pronunciation/v2/swim-aru2-b89f90f3.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/swim-ljspeech-b89f90f3.mp3\", \"/storage/v1/object/public/pronunciation/v2/swi