('47033b5f-5a58-5729-b952-ea42a592c157', '9adb6452-11a5-5b18-bb10-e71549f348f5', '5be9de34-e420-531e-8ced-fad76d931d2f', '3e7de1f0-bbb7-57fb-83cb-f21098efd47b', 'art', '/ɑːt/', 'A2', 'noun', 'sự sáng tạo và thể hiện cái đẹp qua hình ảnh, âm thanh, hay ngôn ngữ.', 'visual or performing works created through human skill and imagination to express ideas or emotions.', 'She enjoys visiting art galleries to see paintings and sculptures.', 'Cô ấy thích đi thăm các phòng trưng bày nghệ thuật để xem tranh và tượng.', '{\"en\": \"The corporate office displays local art to create a welcoming atmosphere for all visiting clients.\", \"vi\": \"Văn phòng công ty trưng bày các tác phẩm nghệ thuật địa phương để tạo bầu không khí chào đón khách hàng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/art-ljspeech-4f468a68.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/art-cori-4f468a68.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/art-17102db7.webp', '[\"creativity\", \"craft\"]', NULL, '[{\"phrase\": \"fine art\", \"meaning\": \"mỹ thuật\"}, {\"phrase\": \"work of art\", \"meaning\": \"tác phẩm nghệ thuật\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"artist\"}, {\"pos\": \"adjective\", \"word\": \"artistic\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/art-cori-4f468a68.mp3\", \"/storage/v1/object/public/pronunciation/v2/art-aru0-4f468a68.mp3\", \"/storage/v1/object/public/pronunciation/v2/art-aru5-4f468a68.mp3\", \"/storage/v1/object/public/pronunciation/v2/art-aru6-4f468a68.mp3\", \"/storage/v1/object/public/pronunciation/v2/art-aru10-4f468a68.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/art-aru9-4f468a68.mp3\", \"/storage/v1/object/public/pronunciation/v2/art-aru3-4f468a68.mp3\", \"/storage/v1/object/public/pronunciation/v2/art-aru7-4f468a68.mp3\", \"/storage/v1/object/public/pronunciation/v2/art-aru8-4f468a68.mp3\", \"/storage/v1/object/public/pronunciation/v2/art-aru2-4f468a68.mp3\"]},