('857c879e-98d7-5197-bc77-fc8fbb773aad', '9adb6452-11a5-5b18-bb10-e71549f348f5', '657d1539-d819-5036-9629-00f95c45f83a', '77a83f4d-0615-53f2-9d23-a0a049f77671', 'bake', 'UK: /beɪkt/ | US: /beɪkt/', 'A2', 'adjective', 'được nướng', 'cooked by exposure to dry radiant heat inside a closed oven without direct contact with flame', 'The restaurant serves delicious baked potatoes.', 'Nhà hàng phục vụ khoai tây nướng rất ngon.', '{\"en\": \"The corporate cafeteria serves freshly bake items every morning for breakfast.\", \"vi\": \"Nhà ăn công ty phục vụ các món được nướng tươi mới mỗi sáng cho bữa sáng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/bake-ljspeech-74521faf.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/bake-cori-74521faf.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/bake-5b8a62ac.webp', '[\"roasted\", \"cooked\"]', '[\"raw\", \"unbaked\"]', '[{\"phrase\": \"bake goods\", \"meaning\": \"các mặt hàng đồ nướng\"}, {\"phrase\": \"freshly bake\", \"meaning\": \"được nướng tươi mới\"}]', NULL, '[{\"pos\": \"verb\", \"word\": \"bake\"}, {\"pos\": \"noun\", \"word\": \"baker\"}, {\"pos\": \"noun\", \"word\": \"bakery\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/bake-cori-74521faf.mp3\", \"/storage/v1/object/public/pronunciation/v2/bake-aru0-74521faf.mp3\", \"/storage/v1/object/public/pronunciation/v2/bake-aru5-74521faf.mp3\", \"/storage/v1/object/public/pronunciation/v2/bake-aru6-74521faf.mp3\", \"/storage/v1/object/public/pronunciation/v2/bake-aru10-74521faf.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/bake-aru9-74521faf.mp3\", \"/storage/v1/object/public/pronunciation/v2/bake-aru3-74521faf.mp3\", \"/storage/v1/object/public/pronunciation/v2/bake-aru7-74521faf.mp3\", \"/storage/v1/object/public/pronunciation/v2/bake-aru8-74521faf.mp3\", \"/storage/v1/object/public/pronunciation/v2/bake-aru2-74521faf.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/