('d7339868-6405-5896-84c6-9d9a594e5307', '9adb6452-11a5-5b18-bb10-e71549f348f5', '7b5a43e9-1d14-5ef1-beac-9881cf0d4f70', '14ac4612-4477-5151-bd24-410b1bca5021', 'headphone', 'UK: /ˈhɛdˌfəʊn/ | US: /ˈhɛdˌfoʊn/', 'A2', 'noun', 'tai nghe', 'An electronic audio device worn over or inside ears to listen to sound privately.', 'I use headphones for online meetings.', 'Tôi dùng tai nghe cho các cuộc họp trực tuyến.', '{\"en\": \"Please wear headphones when listening to audio files in the open-plan office.\", \"vi\": \"Vui lòng đeo tai nghe khi nghe các tệp âm thanh trong văn phòng không gian mở.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/headphone-ljspeech-6900797c.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/headphone-cori-6900797c.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/headphone-ea7bad45.webp', '[\"headset\", \"earphones\"]', NULL, '[{\"phrase\": \"noise-canceling headphones\", \"meaning\": \"tai nghe chống ồn\"}, {\"phrase\": \"wear headphones\", \"meaning\": \"đeo tai nghe\"}]', '[{\"word\": \"headset\", \"note_vi\": \"\'Headset\' thường là tai nghe có kèm micrô nói, rất phổ biến ở trung tâm CSKH.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/headphone-cori-6900797c.mp3\", \"/storage/v1/object/public/pronunciation/v2/headphone-aru0-6900797c.mp3\", \"/storage/v1/object/public/pronunciation/v2/headphone-aru5-6900797c.mp3\", \"/storage/v1/object/public/pronunciation/v2/headphone-aru6-6900797c.mp3\", \"/storage/v1/object/public/pronunciation/v2/headphone-aru10-6900797c.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/headphone-aru9-6900797c.mp3\", \"/storage/v1/object/public/pronunciation/v2/headphone-aru3-6900797c.mp3\", \"/storage/v1/object/public/pronunciation/v2/headphone-aru7-6900797c.mp3\", \"/storage/v1/object/public/pronunciation/v2/headphone-aru8-6900797c.mp3\", \"/storage/v1/object/public/pronunciation/v2/headphone-aru2-6900797c.mp3\"]}, \"us\": {\"nu\"