('df8aab42-8f99-5747-b764-30b434ff8f86', '9adb6452-11a5-5b18-bb10-e71549f348f5', '7e434e36-4922-57b9-8dc6-ffe3cf11b514', '07499b71-4662-527d-8f7a-e0b02bce38dd', 'further', 'UK: /ˈfɜːðər/ | US: /ˈfɜrðər/', 'A2', 'adjective', 'thêm nữa, xa hơn', 'more distant or advanced, or added beyond what already exists.', 'We need further discussion on this matter.', 'Chúng ta cần thảo luận thêm về vấn đề này.', '{\"en\": \"Please contact customer support if you require further assistance with your order.\", \"vi\": \"Vui lòng liên hệ bộ phận hỗ trợ khách hàng nếu bạn cần thêm sự trợ giúp về đơn hàng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/further-ljspeech-8aeff27d.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/further-cori-8aeff27d.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/further-66b29761.webp', '[\"additional\", \"extra\", \"supplementary\", \"more\"]', NULL, '[{\"phrase\": \"further information\", \"meaning\": \"thông tin thêm\"}, {\"phrase\": \"further details\", \"meaning\": \"chi tiết bổ sung\"}, {\"phrase\": \"without further delay\", \"meaning\": \"không trì hoãn thêm nữa\"}]', '[{\"word\": \"farther\", \"note_vi\": \"\'further\' dùng rộng rãi cho cả thông tin/mức độ lẫn địa lý; \'farther\' chủ yếu chỉ khoảng cách vật lý.\"}]', '[{\"pos\": \"verb\", \"word\": \"further\"}, {\"pos\": \"noun\", \"word\": \"furtherance\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/further-cori-8aeff27d.mp3\", \"/storage/v1/object/public/pronunciation/v2/further-aru0-8aeff27d.mp3\", \"/storage/v1/object/public/pronunciation/v2/further-aru5-8aeff27d.mp3\", \"/storage/v1/object/public/pronunciation/v2/further-aru6-8aeff27d.mp3\", \"/storage/v1/object/public/pronunciation/v2/further-aru10-8aeff27d.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/further-aru9-8aeff27d.mp3\", \"/storage/v1/object/public/pronunciation/v2/further-aru3-8aeff27d.mp3\", \"/storage/v1/object/public/pronunciation/v2