('a299b39c-acd7-5ab0-91ee-03e15f431ff5', '9adb6452-11a5-5b18-bb10-e71549f348f5', '7e434e36-4922-57b9-8dc6-ffe3cf11b514', '07499b71-4662-527d-8f7a-e0b02bce38dd', 'count', 'UK: /kaʊnt/ | US: /kaʊnt/', 'A2', 'verb', 'đếm', 'to calculate the total number of people or things in a group systematically', 'Please count the money carefully.', 'Hãy đếm tiền cẩn thận.', '{\"en\": \"The auditor will count the inventory items in the warehouse this afternoon.\", \"vi\": \"Kiểm toán viên sẽ đếm các mặt hàng tồn kho trong kho vào chiều nay.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/count-ljspeech-ee9f38e1.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/count-cori-ee9f38e1.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/count-2f640ccf.webp', '[\"calculate\", \"tally\", \"enumerate\", \"compute\"]', '[\"ignore\", \"disregard\"]', '[{\"phrase\": \"count inventory\", \"meaning\": \"đếm/kiểm kê hàng tồn kho\"}, {\"phrase\": \"count on\", \"meaning\": \"dựa vào, tin tưởng vào\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"count\"}, {\"pos\": \"adjective\", \"word\": \"countable\"}, {\"pos\": \"adjective\", \"word\": \"countless\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/count-cori-ee9f38e1.mp3\", \"/storage/v1/object/public/pronunciation/v2/count-aru0-ee9f38e1.mp3\", \"/storage/v1/object/public/pronunciation/v2/count-aru5-ee9f38e1.mp3\", \"/storage/v1/object/public/pronunciation/v2/count-aru6-ee9f38e1.mp3\", \"/storage/v1/object/public/pronunciation/v2/count-aru10-ee9f38e1.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/count-aru9-ee9f38e1.mp3\", \"/storage/v1/object/public/pronunciation/v2/count-aru3-ee9f38e1.mp3\", \"/storage/v1/object/public/pronunciation/v2/count-aru7-ee9f38e1.mp3\", \"/storage/v1/object/public/pronunciation/v2/count-aru8-ee9f38e1.mp3\", \"/storage/v1/object/public/pronunciation/v2/count-aru2-ee9f38e1.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/