('3fbade4d-d8ed-5265-a157-0eca28b228af', '9adb6452-11a5-5b18-bb10-e71549f348f5', '7e434e36-4922-57b9-8dc6-ffe3cf11b514', '07499b71-4662-527d-8f7a-e0b02bce38dd', 'turn', '/tɜːn/', 'A1', 'verb', 'Di chuyển hoặc thay đổi hướng.', 'to move or rotate so as to face another direction.', 'Drivers should turn right immediately after passing the central bank building.', 'Các tài xế nên rẽ phải ngay sau khi đi qua tòa nhà ngân hàng trung ương.', '{\"en\": \"Please turn the prototype to show the client its features.\", \"vi\": \"Hãy xoay mẫu thử để cho khách hàng thấy các tính năng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/turn-ljspeech-b09c738b.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/turn-cori-b09c738b.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/turn-341b4a05.webp', '[\"rotate\", \"spin\", \"veer\"]', NULL, '[{\"phrase\": \"turn down\", \"meaning\": \"từ chối\"}, {\"phrase\": \"turn in\", \"meaning\": \"nộp lại\"}, {\"phrase\": \"turn around\", \"meaning\": \"xoay hướng, cải thiện\"}]', '[{\"word\": \"return\", \"note_vi\": \"trả lại, quay lại, dễ nhầm nghĩa\"}]', '[{\"pos\": \"noun\", \"word\": \"turn\"}, {\"pos\": \"noun\", \"word\": \"turning\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/turn-cori-b09c738b.mp3\", \"/storage/v1/object/public/pronunciation/v2/turn-aru0-b09c738b.mp3\", \"/storage/v1/object/public/pronunciation/v2/turn-aru5-b09c738b.mp3\", \"/storage/v1/object/public/pronunciation/v2/turn-aru6-b09c738b.mp3\", \"/storage/v1/object/public/pronunciation/v2/turn-aru10-b09c738b.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/turn-aru9-b09c738b.mp3\", \"/storage/v1/object/public/pronunciation/v2/turn-aru3-b09c738b.mp3\", \"/storage/v1/object/public/pronunciation/v2/turn-aru7-b09c738b.mp3\", \"/storage/v1/object/public/pronunciation/v2/turn-aru8-b09c738b.mp3\", \"/storage/v1/object/public/pronunciation/v2/turn-aru2-b09c738b.mp3\"]}, \"us\": {\"nu\": [\"/storag