('4344f3ff-f753-5caa-a85e-dcb5297a6d46', '9adb6452-11a5-5b18-bb10-e71549f348f5', 'b1480db3-22df-58eb-aff0-9113b4cce761', '27301452-0f9d-5a6f-8805-3b9e4c72b139', 'bookshelf', 'UK: /ˈbʊk.ʃelf/ | US: /ˈbʊk.ʃelf/', 'A2', 'noun', 'giá sách', 'a flat horizontal surface attached to a wall or frame for holding reading materials', 'He arranged the books neatly on the bookshelf.', 'Anh ấy sắp xếp sách gọn gàng trên giá sách.', '{\"en\": \"The assistant organized all the training manuals neatly on the top bookshelf.\", \"vi\": \"Trợ lý đã sắp xếp tất cả các tài liệu huấn luyện một cách gọn gàng trên giá sách trên cùng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/bookshelf-ljspeech-8e435573.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/bookshelf-cori-8e435573.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/bookshelf-8e897475.webp', '[\"bookcase\", \"shelf\"]', NULL, '[{\"phrase\": \"stacked on the bookshelf\", \"meaning\": \"được xếp chồng trên giá sách\"}, {\"phrase\": \"wall-mounted bookshelf\", \"meaning\": \"giá sách treo tường\"}]', '[{\"word\": \"bookcase\", \"note_vi\": \"Bookshelf là giá/kệ sách đơn lẻ, còn bookcase là cả một tủ sách hoàn chỉnh.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/bookshelf-cori-8e435573.mp3\", \"/storage/v1/object/public/pronunciation/v2/bookshelf-aru0-8e435573.mp3\", \"/storage/v1/object/public/pronunciation/v2/bookshelf-aru5-8e435573.mp3\", \"/storage/v1/object/public/pronunciation/v2/bookshelf-aru6-8e435573.mp3\", \"/storage/v1/object/public/pronunciation/v2/bookshelf-aru10-8e435573.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/bookshelf-aru9-8e435573.mp3\", \"/storage/v1/object/public/pronunciation/v2/bookshelf-aru3-8e435573.mp3\", \"/storage/v1/object/public/pronunciation/v2/bookshelf-aru7-8e435573.mp3\", \"/storage/v1/object/public/pronunciation/v2/bookshelf-aru8-8e435573.mp3\", \"/storage/v1/object/public/pronunciation/v2/bookshelf-