('56a278da-e156-57a6-994d-a4bd29ed7b94', '9adb6452-11a5-5b18-bb10-e71549f348f5', 'b1480db3-22df-58eb-aff0-9113b4cce761', '27301452-0f9d-5a6f-8805-3b9e4c72b139', 'run', '/rʌn/', 'A1', 'verb', 'Di chuyển nhanh bằng chân.', 'to move fast using your legs, moving faster than when you walk.', 'He prefers to run around the sports stadium after finishing his work.', 'Anh ấy thích chạy bộ xung quanh sân vận động thể thao sau khi hoàn thành công việc.', '{\"en\": \"The delivery person had to run to make it to the office before noon.\", \"vi\": \"Nhân viên giao hàng đã phải chạy để đến văn phòng trước giữa trưa.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/run-ljspeech-df6ad190.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/run-cori-df6ad190.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/run-c00431de.webp', '[\"jog\", \"dash\", \"sprint\"]', '[\"walk\"]', '[{\"phrase\": \"run fast\", \"meaning\": \"chạy nhanh\"}, {\"phrase\": \"run a race\", \"meaning\": \"chạy đua\"}]', '[{\"word\": \"jog\", \"note_vi\": \"jog là chạy bộ thong thả để tập thể dục\"}]', '[{\"pos\": \"noun\", \"word\": \"runner\"}, {\"pos\": \"noun\", \"word\": \"running\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/run-cori-df6ad190.mp3\", \"/storage/v1/object/public/pronunciation/v2/run-aru0-df6ad190.mp3\", \"/storage/v1/object/public/pronunciation/v2/run-aru5-df6ad190.mp3\", \"/storage/v1/object/public/pronunciation/v2/run-aru6-df6ad190.mp3\", \"/storage/v1/object/public/pronunciation/v2/run-aru10-df6ad190.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/run-aru9-df6ad190.mp3\", \"/storage/v1/object/public/pronunciation/v2/run-aru3-df6ad190.mp3\", \"/storage/v1/object/public/pronunciation/v2/run-aru7-df6ad190.mp3\", \"/storage/v1/object/public/pronunciation/v2/run-aru8-df6ad190.mp3\", \"/storage/v1/object/public/pronunciation/v2/run-aru2-df6ad190.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v