('686c1708-8792-54e6-9240-ee7e69dc8c68', '9adb6452-11a5-5b18-bb10-e71549f348f5', 'b1480db3-22df-58eb-aff0-9113b4cce761', '27301452-0f9d-5a6f-8805-3b9e4c72b139', 'pound', '/paʊnd/', 'A2', 'noun', 'đơn vị đo trọng lượng tương đương khoảng 0.45 kg.', 'a unit for measuring weight that is equal to approximately 454 grams.', 'The recipe calls for one pound of sugar.', 'Công thức này yêu cầu một pao đường.', '{\"en\": \"The shipping cost is calculated based on every pound of the total package weight.\", \"vi\": \"Chi phí vận chuyển được tính dựa trên mỗi pao tổng trọng lượng của kiện hàng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/pound-ljspeech-dad7d5e0.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/pound-cori-dad7d5e0.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/pound-408602ff.webp', NULL, NULL, '[{\"phrase\": \"per pound\", \"meaning\": \"mỗi pao\"}, {\"phrase\": \"half a pound\", \"meaning\": \"nửa pao\"}]', '[{\"word\": \"pond\", \"note_vi\": \"nghĩa là cái ao, dễ nhầm mặt chữ\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/pound-cori-dad7d5e0.mp3\", \"/storage/v1/object/public/pronunciation/v2/pound-aru0-dad7d5e0.mp3\", \"/storage/v1/object/public/pronunciation/v2/pound-aru5-dad7d5e0.mp3\", \"/storage/v1/object/public/pronunciation/v2/pound-aru6-dad7d5e0.mp3\", \"/storage/v1/object/public/pronunciation/v2/pound-aru10-dad7d5e0.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/pound-aru9-dad7d5e0.mp3\", \"/storage/v1/object/public/pronunciation/v2/pound-aru3-dad7d5e0.mp3\", \"/storage/v1/object/public/pronunciation/v2/pound-aru7-dad7d5e0.mp3\", \"/storage/v1/object/public/pronunciation/v2/pound-aru8-dad7d5e0.mp3\", \"/storage/v1/object/public/pronunciation/v2/pound-aru2-dad7d5e0.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/pound-ljspeech-dad7d5e0.mp3\", \"/storage/v1/object/public/pronunciation/v2/pound-lt408-dad7d5e0.mp3\", \"/storage/v1/ob