('ab51a73a-5e7e-5e5a-b8a1-f68eadbaeecd', '9adb6452-11a5-5b18-bb10-e71549f348f5', 'b4f56eac-34c8-5406-9ef0-8e2ed2a5b531', '99ad8e3b-8520-573b-aa26-98236f5cac2e', 'certainly', 'UK: /ˈsɜːtnli/ | US: /ˈsɜrtnli/', 'A2', 'adverb', 'chắc chắn, đương nhiên', 'Used to emphasize that something is definitely true or bound to happen without doubt.', 'We will certainly consider your proposal.', 'Chúng tôi chắc chắn sẽ xem xét đề xuất của bạn.', '{\"en\": \"Upgrading our computer network will certainly improve staff productivity.\", \"vi\": \"Nâng cấp mạng máy tính của chúng ta chắc chắn sẽ cải thiện năng suất làm việc của nhân viên.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/certainly-ljspeech-2146c08a.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/certainly-cori-2146c08a.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/certainly-46011def.webp', '[\"definitely\", \"undoubtedly\", \"surely\", \"absolutely\"]', '[\"uncertainly\", \"doubtfully\"]', '[{\"phrase\": \"certainly will\", \"meaning\": \"chắc chắn sẽ\"}, {\"phrase\": \"most certainly\", \"meaning\": \"rất chắc chắn, hoàn toàn đồng ý\"}]', NULL, '[{\"pos\": \"adjective\", \"word\": \"certain\"}, {\"pos\": \"noun\", \"word\": \"certainty\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/certainly-cori-2146c08a.mp3\", \"/storage/v1/object/public/pronunciation/v2/certainly-aru0-2146c08a.mp3\", \"/storage/v1/object/public/pronunciation/v2/certainly-aru5-2146c08a.mp3\", \"/storage/v1/object/public/pronunciation/v2/certainly-aru6-2146c08a.mp3\", \"/storage/v1/object/public/pronunciation/v2/certainly-aru10-2146c08a.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/certainly-aru9-2146c08a.mp3\", \"/storage/v1/object/public/pronunciation/v2/certainly-aru3-2146c08a.mp3\", \"/storage/v1/object/public/pronunciation/v2/certainly-aru7-2146c08a.mp3\", \"/storage/v1/object/public/pronunciation/v2/certainly-aru8-2146c08a.mp3\", \"/storage/v1/object/pu