('da75684c-7bcd-5767-a84a-55da086ec010', '9adb6452-11a5-5b18-bb10-e71549f348f5', 'bc2e3fb9-e705-5a56-b8ef-ca7f6a07137c', '3392f953-154b-5604-92d6-ae09947beefa', 'wait', '/weɪt/', 'A1', 'verb', 'Ở lại một chỗ cho đến khi điều gì đó xảy ra.', 'to remain stationary or pause expected activities until an expected person or event arrives.', 'Please wait here while I go get the tickets.', 'Xin hãy đợi ở đây trong khi tôi đi lấy vé.', '{\"en\": \"Please wait in the reception area until the manager is ready for your scheduled interview.\", \"vi\": \"Vui lòng đợi ở khu vực lễ tân cho đến khi giám đốc sẵn sàng cho buổi phỏng vấn.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/wait-ljspeech-daaad336.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/wait-cori-daaad336.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/wait-c523385c.webp', '[\"remain\", \"stay\"]', NULL, '[{\"phrase\": \"wait for\", \"meaning\": \"đợi chờ ai/cái gì\"}, {\"phrase\": \"long wait\", \"meaning\": \"sự chờ đợi lâu\"}]', '[{\"word\": \"weight\", \"note_vi\": \"weight là danh từ chỉ cân nặng, phát âm giống wait.\"}]', '[{\"pos\": \"noun\", \"word\": \"waiter\"}, {\"pos\": \"noun\", \"word\": \"waiting\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/wait-cori-daaad336.mp3\", \"/storage/v1/object/public/pronunciation/v2/wait-aru0-daaad336.mp3\", \"/storage/v1/object/public/pronunciation/v2/wait-aru5-daaad336.mp3\", \"/storage/v1/object/public/pronunciation/v2/wait-aru6-daaad336.mp3\", \"/storage/v1/object/public/pronunciation/v2/wait-aru10-daaad336.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/wait-aru9-daaad336.mp3\", \"/storage/v1/object/public/pronunciation/v2/wait-aru3-daaad336.mp3\", \"/storage/v1/object/public/pronunciation/v2/wait-aru7-daaad336.mp3\", \"/storage/v1/object/public/pronunciation/v2/wait-aru8-daaad336.mp3\", \"/storage/v1/object/public/pronunciation/v2/wait-aru2-daaad336.mp3\"]}, \"us\": {\"nu\": [\"