('e6748b64-36f7-585c-b375-f3f43d1f711b', '9adb6452-11a5-5b18-bb10-e71549f348f5', 'bc2e3fb9-e705-5a56-b8ef-ca7f6a07137c', '3392f953-154b-5604-92d6-ae09947beefa', 'brush', 'UK: /brʌʃ/ | US: /brʌʃ/', 'A2', 'verb', 'chải, quét', 'to clean or remove dirt from a surface using an object with stiff bristles or soft sweeping motions', 'Please brush the dust off the equipment.', 'Làm ơn phủi bụi khỏi thiết bị.', '{\"en\": \"The maintenance staff will brush the dust off the office ventilation filters tomorrow morning.\", \"vi\": \"Nhân viên bảo trì sẽ quét sạch bụi khỏi các bộ lọc thông gió của văn phòng vào sáng mai.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/brush-ljspeech-0f445105.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/brush-cori-0f445105.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/brush-d8879c8a.webp', '[\"sweep\", \"clean\", \"scrub\"]', '[\"soil\", \"dirty\"]', '[{\"phrase\": \"brush up on\", \"meaning\": \"ôn lại, trau dồi (kỹ năng)\"}, {\"phrase\": \"brush off\", \"meaning\": \"quét sạch, phủi sạch\"}]', '[{\"word\": \"blush\", \"note_vi\": \"đỏ mặt (vì ngượng)\"}]', '[{\"pos\": \"noun\", \"word\": \"brush\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/brush-cori-0f445105.mp3\", \"/storage/v1/object/public/pronunciation/v2/brush-aru0-0f445105.mp3\", \"/storage/v1/object/public/pronunciation/v2/brush-aru5-0f445105.mp3\", \"/storage/v1/object/public/pronunciation/v2/brush-aru6-0f445105.mp3\", \"/storage/v1/object/public/pronunciation/v2/brush-aru10-0f445105.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/brush-aru9-0f445105.mp3\", \"/storage/v1/object/public/pronunciation/v2/brush-aru3-0f445105.mp3\", \"/storage/v1/object/public/pronunciation/v2/brush-aru7-0f445105.mp3\", \"/storage/v1/object/public/pronunciation/v2/brush-aru8-0f445105.mp3\", \"/storage/v1/object/public/pronunciation/v2/brush-aru2-0f445105.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pron