('084dfe0a-22dc-531a-96f0-f3deb7666bde', '9adb6452-11a5-5b18-bb10-e71549f348f5', 'cb426380-0534-5de5-a1fe-3b273636ac96', '11d2c29a-b472-5f94-97fc-76fd40659831', 'grandmother', '/ˈɡrænmʌðə(r)/', 'A1', 'noun', 'mẹ của bố hoặc mẹ.', 'the female parent of a person\'s father or mother.', 'Her grandmother taught her how to cook traditional dishes when she was young.', 'Bà của cô ấy đã dạy cô ấy cách nấu các món ăn truyền thống khi cô ấy còn nhỏ.', '{\"en\": \"The company sent a gift to the employee\'s grandmother for her birthday.\", \"vi\": \"Công ty đã gửi một món quà đến bà của nhân viên nhân dịp sinh nhật bà ấy.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/grandmother-ljspeech-ea39210a.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/grandmother-cori-ea39210a.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/grandmother-387efa1f.webp', '[\"granny\", \"grandma\"]', NULL, '[{\"phrase\": \"maternal grandmother\", \"meaning\": \"bà ngoại\"}, {\"phrase\": \"paternal grandmother\", \"meaning\": \"bà nội\"}, {\"phrase\": \"grandmother\'s birthday\", \"meaning\": \"sinh nhật bà\"}]', '[{\"word\": \"grandfather\", \"note_vi\": \"chỉ ông, khác giới tính với bà\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/grandmother-cori-ea39210a.mp3\", \"/storage/v1/object/public/pronunciation/v2/grandmother-aru0-ea39210a.mp3\", \"/storage/v1/object/public/pronunciation/v2/grandmother-aru5-ea39210a.mp3\", \"/storage/v1/object/public/pronunciation/v2/grandmother-aru6-ea39210a.mp3\", \"/storage/v1/object/public/pronunciation/v2/grandmother-aru10-ea39210a.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/grandmother-aru9-ea39210a.mp3\", \"/storage/v1/object/public/pronunciation/v2/grandmother-aru3-ea39210a.mp3\", \"/storage/v1/object/public/pronunciation/v2/grandmother-aru7-ea39210a.mp3\", \"/storage/v1/object/public/pronunciation/v2/grandmother-aru8-ea39210a.mp3\", \"/storage/v1/object/public/pronunci