('018568ed-7e88-5ddf-b80f-cfbb1a5ee301', '9adb6452-11a5-5b18-bb10-e71549f348f5', 'd67259fd-0afa-5236-8747-d66f25af3c92', 'f4bc4c58-7869-52e6-90ee-787d365da3a2', 'closet', 'UK: /ˈklɒzɪt/ | US: /ˈklɑːzɪt/', 'A2', 'noun', 'tủ quần áo, buồng nhỏ', 'a small room or tall cupboard used for storing garments and household items.', 'The supplies are stored in the closet.', 'Đồ dùng được cất trong tủ.', '{\"en\": \"All office supplies and extra copy paper are stored in the supply closet on the second floor.\", \"vi\": \"Tất cả văn phòng phẩm và giấy in bổ sung được cất trong tủ đựng đồ ở tầng hai.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/closet-ljspeech-87dc8fb3.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/closet-cori-87dc8fb3.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/closet-2250ef9e.webp', '[\"cupboard\", \"wardrobe\", \"cabinet\"]', NULL, '[{\"phrase\": \"supply closet\", \"meaning\": \"tủ/kho chứa văn phòng phẩm\"}, {\"phrase\": \"walk-in closet\", \"meaning\": \"phòng thay đồ/tủ quần áo cỡ lớn\"}]', NULL, '[{\"pos\": \"verb\", \"word\": \"closet\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/closet-cori-87dc8fb3.mp3\", \"/storage/v1/object/public/pronunciation/v2/closet-aru0-87dc8fb3.mp3\", \"/storage/v1/object/public/pronunciation/v2/closet-aru5-87dc8fb3.mp3\", \"/storage/v1/object/public/pronunciation/v2/closet-aru6-87dc8fb3.mp3\", \"/storage/v1/object/public/pronunciation/v2/closet-aru10-87dc8fb3.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/closet-aru9-87dc8fb3.mp3\", \"/storage/v1/object/public/pronunciation/v2/closet-aru3-87dc8fb3.mp3\", \"/storage/v1/object/public/pronunciation/v2/closet-aru7-87dc8fb3.mp3\", \"/storage/v1/object/public/pronunciation/v2/closet-aru8-87dc8fb3.mp3\", \"/storage/v1/object/public/pronunciation/v2/closet-aru2-87dc8fb3.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/closet-ljspeech-87dc8fb3.mp3\", \"/storage/v1