('c9c481da-7c1a-5cd4-bec8-11e9e92e9946', '9adb6452-11a5-5b18-bb10-e71549f348f5', 'd67259fd-0afa-5236-8747-d66f25af3c92', 'f4bc4c58-7869-52e6-90ee-787d365da3a2', 'clock', '/klɒk/', 'A1', 'noun', 'Thiết bị dùng để hiển thị thời gian, thường đặt trên tường hoặc bàn.', 'an instrument that shows time, usually placed on a wall or table.', 'Please check the digital clock in the meeting room before starting.', 'Vui lòng kiểm tra chiếc đồng hồ điện tử trong phòng họp trước khi bắt đầu.', '{\"en\": \"The wall clock in the meeting room shows that it is three o\'clock.\", \"vi\": \"Chiếc đồng hồ treo tường trong phòng họp cho thấy hiện tại là ba giờ.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/clock-ljspeech-83655a55.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/clock-cori-83655a55.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/clock-40d85386.webp', '[\"timepiece\", \"timer\"]', NULL, '[{\"phrase\": \"alarm clock\", \"meaning\": \"đồng hồ báo thức\"}, {\"phrase\": \"wall clock\", \"meaning\": \"đồng hồ treo tường\"}]', '[{\"word\": \"watch\", \"note_vi\": \"watch là đồng hồ đeo tay, clock là đồng hồ treo tường hoặc để bàn\"}]', '[{\"pos\": \"adverb\", \"word\": \"clockwise\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/clock-cori-83655a55.mp3\", \"/storage/v1/object/public/pronunciation/v2/clock-aru0-83655a55.mp3\", \"/storage/v1/object/public/pronunciation/v2/clock-aru5-83655a55.mp3\", \"/storage/v1/object/public/pronunciation/v2/clock-aru6-83655a55.mp3\", \"/storage/v1/object/public/pronunciation/v2/clock-aru10-83655a55.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/clock-aru9-83655a55.mp3\", \"/storage/v1/object/public/pronunciation/v2/clock-aru3-83655a55.mp3\", \"/storage/v1/object/public/pronunciation/v2/clock-aru7-83655a55.mp3\", \"/storage/v1/object/public/pronunciation/v2/clock-aru8-83655a55.mp3\", \"/storage/v1/object/public/pronunciation/v2/clock-aru2-83655a55.mp3\"]}, \"