('b0925239-43c0-54b5-b8da-17b824f42032', '9adb6452-11a5-5b18-bb10-e71549f348f5', 'de8bb4d7-9e2e-57dc-8785-701817e43a49', '4cc5a6ed-5e5c-56a5-883c-96d2bc3355e7', 'identify', 'UK: /ɪˈdentɪfaɪ/ | US: /ɪˈdentɪfaɪ/', 'A2', 'verb', 'nhận ra, nhận diện', 'To recognize who or what a particular person or thing really is.', 'The manager will identify the cause of the low sales.', 'Người quản lý sẽ xác định nguyên nhân doanh số bán hàng thấp.', '{\"en\": \"The internal audit helped the company identify key areas for cost reduction.\", \"vi\": \"Việc kiểm toán nội bộ đã giúp công ty nhận diện các lĩnh vực then chốt để cắt giảm chi phí.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/identify-ljspeech-9bf0f8ff.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/identify-cori-9bf0f8ff.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/identify-01273440.webp', '[\"recognize\", \"detect\", \"pinpoint\", \"determine\"]', '[\"ignore\", \"overlook\"]', '[{\"phrase\": \"identify problems\", \"meaning\": \"nhận diện các vấn đề\"}, {\"phrase\": \"identify customer needs\", \"meaning\": \"xác định nhu cầu khách hàng\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"identification\"}, {\"pos\": \"adjective\", \"word\": \"identifiable\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/identify-cori-9bf0f8ff.mp3\", \"/storage/v1/object/public/pronunciation/v2/identify-aru0-9bf0f8ff.mp3\", \"/storage/v1/object/public/pronunciation/v2/identify-aru5-9bf0f8ff.mp3\", \"/storage/v1/object/public/pronunciation/v2/identify-aru6-9bf0f8ff.mp3\", \"/storage/v1/object/public/pronunciation/v2/identify-aru10-9bf0f8ff.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/identify-aru9-9bf0f8ff.mp3\", \"/storage/v1/object/public/pronunciation/v2/identify-aru3-9bf0f8ff.mp3\", \"/storage/v1/object/public/pronunciation/v2/identify-aru7-9bf0f8ff.mp3\", \"/storage/v1/object/public/pronunciation/v2/identify-aru8-9bf0f8ff.mp3\", \"/storage/v1/obj