('10863af7-0a91-5a5c-877c-b8753b6ee1bb', '9adb6452-11a5-5b18-bb10-e71549f348f5', 'ea3f0102-3dab-5154-8f93-f8ffc8d40af3', 'd6eeef1a-59cd-5208-91c3-0997b617ab0d', 'wake', '/weɪk/', 'A1', 'verb', 'Tỉnh giấc sau khi ngủ.', 'to stop sleeping and become active or aware of your surroundings.', 'I usually wake up early to go for a run.', 'Tôi thường thức dậy sớm để đi chạy bộ.', '{\"en\": \"The business travelers usually wake up early to attend the morning conference.\", \"vi\": \"Các khách đi công tác thường thức dậy sớm để tham dự hội nghị buổi sáng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/wake-ljspeech-07edc5e2.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/wake-cori-07edc5e2.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/wake-46dc6634.webp', '[\"awaken\", \"arouse\"]', '[\"sleep\"]', '[{\"phrase\": \"wake up early\", \"meaning\": \"thức dậy sớm\"}, {\"phrase\": \"wake someone up\", \"meaning\": \"đánh thức ai dậy\"}]', '[{\"word\": \"awake\", \"note_vi\": \"awake là tính từ hoặc động từ, wake thường đi với up\"}]', '[{\"pos\": \"adjective\", \"word\": \"awake\"}, {\"pos\": \"noun\", \"word\": \"awakening\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/wake-cori-07edc5e2.mp3\", \"/storage/v1/object/public/pronunciation/v2/wake-aru0-07edc5e2.mp3\", \"/storage/v1/object/public/pronunciation/v2/wake-aru5-07edc5e2.mp3\", \"/storage/v1/object/public/pronunciation/v2/wake-aru6-07edc5e2.mp3\", \"/storage/v1/object/public/pronunciation/v2/wake-aru10-07edc5e2.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/wake-aru9-07edc5e2.mp3\", \"/storage/v1/object/public/pronunciation/v2/wake-aru3-07edc5e2.mp3\", \"/storage/v1/object/public/pronunciation/v2/wake-aru7-07edc5e2.mp3\", \"/storage/v1/object/public/pronunciation/v2/wake-aru8-07edc5e2.mp3\", \"/storage/v1/object/public/pronunciation/v2/wake-aru2-07edc5e2.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/wake-ljs