('47718cef-fed5-5170-a16f-5e780bf74869', '9adb6452-11a5-5b18-bb10-e71549f348f5', 'edfb269b-8652-5d1b-b2a0-0de3a2e0c9c9', 'adb327c7-8037-514d-9d07-2d4f77933800', 'show', '/ʃəʊ/', 'A1', 'noun', 'một buổi biểu diễn hoặc sự kiện giải trí công cộng.', 'a performance or program that people watch for entertainment or information.', 'We bought tickets to see a magic show tonight.', 'Chúng tôi đã mua vé để xem một buổi trình diễn ảo thuật tối nay.', '{\"en\": \"The trade show will feature the latest technology from international electronics companies.\", \"vi\": \"Triển lãm thương mại sẽ giới thiệu công nghệ mới nhất từ các công ty điện tử quốc tế.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/show-ljspeech-9fb29051.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/show-cori-9fb29051.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/show-924fa65a.webp', '[\"performance\", \"exhibition\", \"presentation\"]', NULL, '[{\"phrase\": \"trade show\", \"meaning\": \"triển lãm thương mại\"}, {\"phrase\": \"fashion show\", \"meaning\": \"buổi trình diễn thời trang\"}, {\"phrase\": \"talk show\", \"meaning\": \"chương trình trò chuyện\"}]', '[{\"word\": \"shore\", \"note_vi\": \"nghĩa là bờ biển, dễ nhầm cách phát âm\"}]', '[{\"pos\": \"verb\", \"word\": \"show\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/show-cori-9fb29051.mp3\", \"/storage/v1/object/public/pronunciation/v2/show-aru0-9fb29051.mp3\", \"/storage/v1/object/public/pronunciation/v2/show-aru5-9fb29051.mp3\", \"/storage/v1/object/public/pronunciation/v2/show-aru6-9fb29051.mp3\", \"/storage/v1/object/public/pronunciation/v2/show-aru10-9fb29051.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/show-aru9-9fb29051.mp3\", \"/storage/v1/object/public/pronunciation/v2/show-aru3-9fb29051.mp3\", \"/storage/v1/object/public/pronunciation/v2/show-aru7-9fb29051.mp3\", \"/storage/v1/object/public/pronunciation/v2/show-aru8-9fb29051.mp3\", \"/storage/v