('003a0f48-936a-5c81-8e8b-7e9920f45c6c', '9adb6452-11a5-5b18-bb10-e71549f348f5', 'ef9a1bf4-045a-5f2d-9597-b60b36ba944a', 'd169e348-440f-5b71-8b7a-61be8024e61e', 'horse', '/hɔːs/', 'A1', 'noun', 'Con ngựa.', 'a large animal with four legs that people ride or use for pulling heavy things.', 'The farmer rode his horse across the field.', 'Người nông dân cưỡi ngựa đi qua cánh đồng.', '{\"en\": \"The local farm offers horse riding tours for tourists visiting the countryside.\", \"vi\": \"Trang trại địa phương cung cấp các chuyến tham quan cưỡi ngựa cho khách du lịch ghé thăm vùng nông thôn.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/horse-ljspeech-091b5035.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/horse-cori-091b5035.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/horse-a5135c97.webp', '[\"steed\", \"pony\"]', NULL, '[{\"phrase\": \"wild horse\", \"meaning\": \"ngựa hoang\"}, {\"phrase\": \"horse racing\", \"meaning\": \"đua ngựa\"}]', '[{\"word\": \"house\", \"note_vi\": \"ngôi nhà, viết gần giống horse\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/horse-cori-091b5035.mp3\", \"/storage/v1/object/public/pronunciation/v2/horse-aru0-091b5035.mp3\", \"/storage/v1/object/public/pronunciation/v2/horse-aru5-091b5035.mp3\", \"/storage/v1/object/public/pronunciation/v2/horse-aru6-091b5035.mp3\", \"/storage/v1/object/public/pronunciation/v2/horse-aru10-091b5035.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/horse-aru9-091b5035.mp3\", \"/storage/v1/object/public/pronunciation/v2/horse-aru3-091b5035.mp3\", \"/storage/v1/object/public/pronunciation/v2/horse-aru7-091b5035.mp3\", \"/storage/v1/object/public/pronunciation/v2/horse-aru8-091b5035.mp3\", \"/storage/v1/object/public/pronunciation/v2/horse-aru2-091b5035.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/horse-ljspeech-091b5035.mp3\", \"/storage/v1/object/public/pronunciation/v2/horse-lt408-091b50