('7d354202-ea94-5e62-aa5f-0235b79ba593', '9adb6452-11a5-5b18-bb10-e71549f348f5', 'ef9a1bf4-045a-5f2d-9597-b60b36ba944a', 'd169e348-440f-5b71-8b7a-61be8024e61e', 'really', '/ˈriːəli/', 'A1', 'adverb', 'Diễn tả mức độ cao, rất, hoặc khẳng định sự thật.', 'used to emphasize that a statement is true or to show high degree.', 'I really appreciate your help with this difficult task.', 'Tôi thực sự rất cảm kích sự giúp đỡ của bạn với nhiệm vụ khó khăn này.', '{\"en\": \"The client was really satisfied with the prompt delivery of their requested order.\", \"vi\": \"Khách hàng thực sự hài lòng với việc giao đơn hàng đã yêu cầu một cách nhanh chóng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/really-ljspeech-084ab409.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/really-cori-084ab409.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/really-94a61cbe.webp', '[\"truly\", \"actually\", \"genuinely\"]', NULL, '[{\"phrase\": \"really good\", \"meaning\": \"thực sự tốt\"}, {\"phrase\": \"really appreciate\", \"meaning\": \"thực sự trân trọng\"}, {\"phrase\": \"really want\", \"meaning\": \"thực sự muốn\"}]', '[{\"word\": \"rarely\", \"note_vi\": \"rarely nghĩa là hiếm khi, phát âm và nghĩa hoàn toàn khác really\"}]', '[{\"pos\": \"adjective\", \"word\": \"real\"}, {\"pos\": \"noun\", \"word\": \"reality\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/really-cori-084ab409.mp3\", \"/storage/v1/object/public/pronunciation/v2/really-aru0-084ab409.mp3\", \"/storage/v1/object/public/pronunciation/v2/really-aru5-084ab409.mp3\", \"/storage/v1/object/public/pronunciation/v2/really-aru6-084ab409.mp3\", \"/storage/v1/object/public/pronunciation/v2/really-aru10-084ab409.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/really-aru9-084ab409.mp3\", \"/storage/v1/object/public/pronunciation/v2/really-aru3-084ab409.mp3\", \"/storage/v1/object/public/pronunciation/v2/really-aru7-084ab409.mp3\", \"/storage/v1/ob