('5b68aa35-47f0-5125-ba59-c5fd2cf5cded', 'f22c8c20-af01-5c36-b57d-2e84d1a5e7dd', '0d8fd286-2cd1-5ba5-b581-bd8dc0c36794', '07429b81-3344-5b7d-808e-ba48c3e7c3e4', 'essential', 'UK: /ɪˈsenʃəl/ | US: /ɪˈsenʃəl/', 'B1', 'adjective', 'thiết yếu, cần thiết', 'Absolutely necessary or extremely important for a particular task or outcome.', 'Reliable transportation is essential for this role.', 'Phương tiện đi lại đáng tin cậy là thiết yếu cho vai trò này.', '{\"en\": \"Good communication skills are essential for effective teamwork.\", \"vi\": \"Kỹ năng giao tiếp tốt là rất cần thiết cho việc làm việc nhóm hiệu quả.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/essential-ljspeech-16e73bca.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/essential-cori-16e73bca.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/essential-12eae2ff.webp', '[\"crucial\", \"vital\", \"necessary\", \"indispensable\"]', '[\"optional\", \"unnecessary\"]', '[{\"phrase\": \"essential for/to\", \"meaning\": \"thiết yếu cho\"}, {\"phrase\": \"play an essential role\", \"meaning\": \"đóng vai trò thiết yếu\"}]', NULL, '[{\"pos\": \"adverb\", \"word\": \"essentially\"}, {\"pos\": \"noun\", \"word\": \"essence\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/essential-cori-16e73bca.mp3\", \"/storage/v1/object/public/pronunciation/v2/essential-aru0-16e73bca.mp3\", \"/storage/v1/object/public/pronunciation/v2/essential-aru5-16e73bca.mp3\", \"/storage/v1/object/public/pronunciation/v2/essential-aru6-16e73bca.mp3\", \"/storage/v1/object/public/pronunciation/v2/essential-aru10-16e73bca.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/essential-aru9-16e73bca.mp3\", \"/storage/v1/object/public/pronunciation/v2/essential-aru3-16e73bca.mp3\", \"/storage/v1/object/public/pronunciation/v2/essential-aru7-16e73bca.mp3\", \"/storage/v1/object/public/pronunciation/v2/essential-aru8-16e73bca.mp3\", \"/storage/v1/object/public/pronunciation