('51006fdb-d93a-5078-a46a-385c3aaa44f0', 'f22c8c20-af01-5c36-b57d-2e84d1a5e7dd', '10a9dedd-23fd-5131-a49d-e7cbb7941c18', 'edee1df6-4c9c-5f6c-8591-da15d8ff32cf', 'salary', '/ˈsæləri/', 'A2', 'noun', 'số tiền cố định mà một người nhận được thường xuyên từ công việc.', 'a fixed amount of money paid regularly to an employee for their work.', 'His new job offers a much higher salary than his previous one.', 'Công việc mới của anh ấy trả mức lương cao hơn nhiều so với công việc trước.', '{\"en\": \"The company offers a competitive salary along with comprehensive health insurance benefits.\", \"vi\": \"Công ty cung cấp mức lương cạnh tranh cùng với các lợi ích bảo hiểm y tế toàn diện.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/salary-ljspeech-47dfeb55.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/salary-cori-47dfeb55.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/salary-23658b8e.webp', '[\"pay\", \"wage\"]', NULL, '[{\"phrase\": \"competitive salary\", \"meaning\": \"mức lương cạnh tranh\"}, {\"phrase\": \"annual salary\", \"meaning\": \"lương hàng năm\"}, {\"phrase\": \"salary increase\", \"meaning\": \"sự tăng lương\"}]', '[{\"word\": \"wage\", \"note_vi\": \"salary trả theo tháng/năm cố định, wage trả theo giờ/ngày\"}]', '[{\"pos\": \"adjective\", \"word\": \"salaried\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/salary-cori-47dfeb55.mp3\", \"/storage/v1/object/public/pronunciation/v2/salary-aru0-47dfeb55.mp3\", \"/storage/v1/object/public/pronunciation/v2/salary-aru5-47dfeb55.mp3\", \"/storage/v1/object/public/pronunciation/v2/salary-aru6-47dfeb55.mp3\", \"/storage/v1/object/public/pronunciation/v2/salary-aru10-47dfeb55.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/salary-aru9-47dfeb55.mp3\", \"/storage/v1/object/public/pronunciation/v2/salary-aru3-47dfeb55.mp3\", \"/storage/v1/object/public/pronunciation/v2/salary-aru7-47dfeb55.mp3\", \"/storage/v1/object/public/pronun