('a3758b74-efa7-508f-b4dc-202c7e17da62', 'f22c8c20-af01-5c36-b57d-2e84d1a5e7dd', '27ef85aa-45c7-58f7-9a43-8a9165a9d43b', 'e81f6ed0-9874-5413-821d-60e2defb18cd', 'article', 'UK: /ˈɑːtɪkl̩/ | US: /ˈɑːrtɪkl̩/', 'A2', 'noun', 'bài báo', 'a piece of writing included with others in a newspaper, magazine, or online publication', 'The newspaper published a long article about the economy.', 'Tờ báo đăng một bài dài về kinh tế.', '{\"en\": \"The business magazine published an article featuring our company\'s sustainable practices.\", \"vi\": \"Tạp chí kinh doanh đã đăng một bài báo nêu bật các hoạt động phát triển bền vững của công ty chúng tôi.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/article-ljspeech-565cecd7.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/article-cori-565cecd7.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/article-3e9a3b23.webp', '[\"report\", \"piece\", \"story\", \"item\"]', NULL, '[{\"phrase\": \"publish an article\", \"meaning\": \"xuất bản/đăng một bài báo\"}, {\"phrase\": \"newspaper article\", \"meaning\": \"bài báo trên báo giấy\"}]', NULL, NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/article-cori-565cecd7.mp3\", \"/storage/v1/object/public/pronunciation/v2/article-aru0-565cecd7.mp3\", \"/storage/v1/object/public/pronunciation/v2/article-aru5-565cecd7.mp3\", \"/storage/v1/object/public/pronunciation/v2/article-aru6-565cecd7.mp3\", \"/storage/v1/object/public/pronunciation/v2/article-aru10-565cecd7.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/article-aru9-565cecd7.mp3\", \"/storage/v1/object/public/pronunciation/v2/article-aru3-565cecd7.mp3\", \"/storage/v1/object/public/pronunciation/v2/article-aru7-565cecd7.mp3\", \"/storage/v1/object/public/pronunciation/v2/article-aru8-565cecd7.mp3\", \"/storage/v1/object/public/pronunciation/v2/article-aru2-565cecd7.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/article-ljspeech-565cec