('4369524b-40e1-5c57-a07e-b23f93901077', 'f22c8c20-af01-5c36-b57d-2e84d1a5e7dd', '2d826c76-8fc0-5a1e-9c99-9fc7dee214dc', 'e0545300-07e8-5ea7-89b0-040a363250e2', 'pill', 'UK: /pɪl/ | US: /pɪl/', 'B1', 'noun', 'viên thuốc', 'a small solid mass of medicine to be swallowed whole.', 'Take one pill daily with water.', 'Uống một viên thuốc mỗi ngày với nước.', '{\"en\": \"The company doctor advised the employee to take a pain-relieving pill after hours of continuous desk work.\", \"vi\": \"Bác sĩ công ty khuyên nhân viên nên uống một viên thuốc giảm đau sau nhiều giờ làm việc liên tục tại bàn.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/pill-ljspeech-93720caa.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/pill-cori-93720caa.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/pill-ee713779.webp', '[\"tablet\", \"capsule\", \"medication\"]', NULL, '[{\"phrase\": \"take a pill\", \"meaning\": \"uống một viên thuốc\"}, {\"phrase\": \"sleeping pill\", \"meaning\": \"thuốc ngủ\"}]', '[{\"word\": \"pile\", \"note_vi\": \"Pile nghĩa là chất đống hoặc đống tài liệu/vật dụng.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/pill-cori-93720caa.mp3\", \"/storage/v1/object/public/pronunciation/v2/pill-aru0-93720caa.mp3\", \"/storage/v1/object/public/pronunciation/v2/pill-aru5-93720caa.mp3\", \"/storage/v1/object/public/pronunciation/v2/pill-aru6-93720caa.mp3\", \"/storage/v1/object/public/pronunciation/v2/pill-aru10-93720caa.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/pill-aru9-93720caa.mp3\", \"/storage/v1/object/public/pronunciation/v2/pill-aru3-93720caa.mp3\", \"/storage/v1/object/public/pronunciation/v2/pill-aru7-93720caa.mp3\", \"/storage/v1/object/public/pronunciation/v2/pill-aru8-93720caa.mp3\", \"/storage/v1/object/public/pronunciation/v2/pill-aru2-93720caa.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/pill-ljspeech-93720caa.mp3\", \"/storage/v1/object/pu