('720f9619-c817-5da1-9060-69bd41494148', 'f22c8c20-af01-5c36-b57d-2e84d1a5e7dd', '3b68733e-8e37-548d-8a0a-66fdc219770e', '7d2e9f60-6185-556d-8ac9-c44e52b25482', 'pressure', 'UK: /ˈprɛʃə/ | US: /ˈprɛʃər/', 'B1', 'noun', 'áp lực', 'continuous physical force or psychological stress exerted upon a person, object, or system', 'Employees are under pressure to meet sales targets.', 'Nhân viên chịu áp lực để đạt mục tiêu doanh số.', '{\"en\": \"The sales team is under heavy pressure to meet their quarterly revenue targets.\", \"vi\": \"Đội ngũ bán hàng đang chịu áp lực lớn để đạt chỉ tiêu doanh thu quý.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/pressure-ljspeech-3b4c0c65.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/pressure-cori-3b4c0c65.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/pressure-251dba18.webp', '[\"stress\", \"strain\", \"burden\", \"tension\"]', '[\"relief\", \"relaxation\"]', '[{\"phrase\": \"under pressure\", \"meaning\": \"chịu áp lực\"}, {\"phrase\": \"work well under pressure\", \"meaning\": \"làm việc tốt dưới áp lực\"}, {\"phrase\": \"peer pressure\", \"meaning\": \"áp lực đồng nghiệp/bạn bè\"}]', NULL, '[{\"pos\": \"verb\", \"word\": \"press\"}, {\"pos\": \"verb\", \"word\": \"pressurize\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/pressure-cori-3b4c0c65.mp3\", \"/storage/v1/object/public/pronunciation/v2/pressure-aru0-3b4c0c65.mp3\", \"/storage/v1/object/public/pronunciation/v2/pressure-aru5-3b4c0c65.mp3\", \"/storage/v1/object/public/pronunciation/v2/pressure-aru6-3b4c0c65.mp3\", \"/storage/v1/object/public/pronunciation/v2/pressure-aru10-3b4c0c65.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/pressure-aru9-3b4c0c65.mp3\", \"/storage/v1/object/public/pronunciation/v2/pressure-aru3-3b4c0c65.mp3\", \"/storage/v1/object/public/pronunciation/v2/pressure-aru7-3b4c0c65.mp3\", \"/storage/v1/object/public/pronunciation/v2/pressure-aru8-3b4c0c65.mp3\", \"/s