('796cd836-4b74-5f68-9703-d1e08be2e453', 'f22c8c20-af01-5c36-b57d-2e84d1a5e7dd', '3b68733e-8e37-548d-8a0a-66fdc219770e', '7d2e9f60-6185-556d-8ac9-c44e52b25482', 'employee', '/ɪmˈplɔɪiː/', 'A2', 'noun', 'người làm việc cho một công ty hoặc cá nhân', 'a person who is paid to work for an organization or for another person.', 'All employees are invited to the annual company picnic.', 'Tất cả nhân viên được mời đến buổi dã ngoại thường niên của công ty.', '{\"en\": \"Every employee must submit their weekly time sheet to the human resources department by Friday.\", \"vi\": \"Mỗi nhân viên phải nộp bảng chấm công hàng tuần cho phòng nhân sự trước thứ Sáu.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/employee-ljspeech-caf322f0.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/employee-cori-caf322f0.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/employee-250fd489.webp', '[\"staff\", \"worker\"]', '[\"employer\"]', '[{\"phrase\": \"full-time employee\", \"meaning\": \"nhân viên toàn thời gian\"}, {\"phrase\": \"hire an employee\", \"meaning\": \"thuê nhân viên\"}]', '[{\"word\": \"employer\", \"note_vi\": \"Employer là người thuê (ông chủ), employee là người được thuê.\"}]', '[{\"pos\": \"noun\", \"word\": \"employment\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/employee-cori-caf322f0.mp3\", \"/storage/v1/object/public/pronunciation/v2/employee-aru0-caf322f0.mp3\", \"/storage/v1/object/public/pronunciation/v2/employee-aru5-caf322f0.mp3\", \"/storage/v1/object/public/pronunciation/v2/employee-aru6-caf322f0.mp3\", \"/storage/v1/object/public/pronunciation/v2/employee-aru10-caf322f0.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/employee-aru9-caf322f0.mp3\", \"/storage/v1/object/public/pronunciation/v2/employee-aru3-caf322f0.mp3\", \"/storage/v1/object/public/pronunciation/v2/employee-aru7-caf322f0.mp3\", \"/storage/v1/object/public/pronunciation/v2/employee-aru8-caf322f0.mp3\", \"/st