('18390a7b-5bf9-580d-a65b-9a546aeeeb97', 'f22c8c20-af01-5c36-b57d-2e84d1a5e7dd', '4335ca0d-f5e6-5639-8b75-9d01ee5197a5', '8fadb5a7-c236-5e83-abd3-0c38a96c293c', 'microphone', 'UK: /ˈmaɪkrəʊfəʊn/ | US: /ˈmaɪkroʊfoʊn/', 'A2', 'noun', 'micro, micro âm thanh', 'an electronic device used to record sounds or make voices sound louder.', 'The presenter will speak into the microphone.', 'Người thuyết trình sẽ nói vào micro.', '{\"en\": \"Please ensure your microphone is muted during the conference call to avoid background noise.\", \"vi\": \"Vui lòng đảm bảo rằng micro của bạn đã được tắt tiếng trong cuộc họp trực tuyến để tránh tiếng ồn xung quanh.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/microphone-ljspeech-17d39602.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/microphone-cori-17d39602.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/microphone-516efcf0.webp', '[\"mic\", \"transmitter\"]', NULL, '[{\"phrase\": \"speak into the microphone\", \"meaning\": \"nói vào micro\"}, {\"phrase\": \"wireless microphone\", \"meaning\": \"micro không dây\"}]', '[{\"word\": \"microscope\", \"note_vi\": \"Microscope là kính hiển vi để quan sát vật nhỏ, còn microphone là thiết bị thu âm thanh.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/microphone-cori-17d39602.mp3\", \"/storage/v1/object/public/pronunciation/v2/microphone-aru0-17d39602.mp3\", \"/storage/v1/object/public/pronunciation/v2/microphone-aru5-17d39602.mp3\", \"/storage/v1/object/public/pronunciation/v2/microphone-aru6-17d39602.mp3\", \"/storage/v1/object/public/pronunciation/v2/microphone-aru10-17d39602.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/microphone-aru9-17d39602.mp3\", \"/storage/v1/object/public/pronunciation/v2/microphone-aru3-17d39602.mp3\", \"/storage/v1/object/public/pronunciation/v2/microphone-aru7-17d39602.mp3\", \"/storage/v1/object/public/pronunciation/v2/microphone-aru8-17d39602.mp3\", \"/storage/v1/o