('1ed236e3-791f-5a2b-83d0-37799b6ee358', 'f22c8c20-af01-5c36-b57d-2e84d1a5e7dd', '518f1783-4de0-5475-ac2e-bd5eace06290', '8618bad3-c8f1-5fae-88a9-188ccc8784d1', 'liquid', 'UK: /ˈlɪkwɪd/ | US: /ˈlɪkwɪd/', 'B1', 'noun', 'chất lỏng', 'a substance that flows freely, having a definite volume but no permanent shape.', 'The medication is available in liquid form.', 'Thuốc này có ở dạng chất lỏng.', '{\"en\": \"Airport security regulations prohibit passengers from carrying any liquid over 100ml in their hand luggage.\", \"vi\": \"Quy định an ninh sân bay cấm hành khách mang bất kỳ chất lỏng nào trên 100ml trong hành lý xách tay.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/liquid-ljspeech-91d9c4ec.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/liquid-cori-91d9c4ec.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/liquid-46035bd4.webp', '[\"fluid\", \"solution\"]', '[\"solid\", \"gas\"]', '[{\"phrase\": \"liquid detergent\", \"meaning\": \"nước giặt tẩy\"}, {\"phrase\": \"toxic liquid\", \"meaning\": \"chất lỏng độc hại\"}]', '[{\"word\": \"liquor\", \"note_vi\": \"Rượu mạnh chứ không phải chất lỏng nói chung\"}]', '[{\"pos\": \"adjective\", \"word\": \"liquid\"}, {\"pos\": \"verb\", \"word\": \"liquidate\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/liquid-cori-91d9c4ec.mp3\", \"/storage/v1/object/public/pronunciation/v2/liquid-aru0-91d9c4ec.mp3\", \"/storage/v1/object/public/pronunciation/v2/liquid-aru5-91d9c4ec.mp3\", \"/storage/v1/object/public/pronunciation/v2/liquid-aru6-91d9c4ec.mp3\", \"/storage/v1/object/public/pronunciation/v2/liquid-aru10-91d9c4ec.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/liquid-aru9-91d9c4ec.mp3\", \"/storage/v1/object/public/pronunciation/v2/liquid-aru3-91d9c4ec.mp3\", \"/storage/v1/object/public/pronunciation/v2/liquid-aru7-91d9c4ec.mp3\", \"/storage/v1/object/public/pronunciation/v2/liquid-aru8-91d9c4ec.mp3\", \"/storage/v1/object/public/pronunci