('40280a4b-b79d-5317-bb05-09a0d091a135', 'f22c8c20-af01-5c36-b57d-2e84d1a5e7dd', '518f1783-4de0-5475-ac2e-bd5eace06290', '8618bad3-c8f1-5fae-88a9-188ccc8784d1', 'handle', 'UK: /ˈhændl/ | US: /ˈhændl/', 'B1', 'verb', 'xử lý, giải quyết', 'to deal with, manage, or take care of a situation or problem.', 'Please handle these fragile items with care.', 'Vui lòng xử lý những món đồ dễ vỡ này cẩn thận.', '{\"en\": \"The customer service representative efficiently handled the client\'s complaint.\", \"vi\": \"Đại diện dịch vụ khách hàng đã xử lý phàn nàn của khách hàng một cách hiệu quả.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/handle-ljspeech-a2dd7ec6.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/handle-cori-a2dd7ec6.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/handle-4ca8225e.webp', '[\"manage\", \"deal with\", \"address\", \"tackle\"]', '[\"ignore\", \"neglect\"]', '[{\"phrase\": \"handle customer inquiries\", \"meaning\": \"xử lý thắc mắc của khách hàng\"}, {\"phrase\": \"handle a complaint\", \"meaning\": \"giải quyết khiếu nại\"}]', NULL, '[{\"pos\": \"noun\", \"word\": \"handler\"}, {\"pos\": \"noun\", \"word\": \"handle\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/handle-cori-a2dd7ec6.mp3\", \"/storage/v1/object/public/pronunciation/v2/handle-aru0-a2dd7ec6.mp3\", \"/storage/v1/object/public/pronunciation/v2/handle-aru5-a2dd7ec6.mp3\", \"/storage/v1/object/public/pronunciation/v2/handle-aru6-a2dd7ec6.mp3\", \"/storage/v1/object/public/pronunciation/v2/handle-aru10-a2dd7ec6.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/handle-aru9-a2dd7ec6.mp3\", \"/storage/v1/object/public/pronunciation/v2/handle-aru3-a2dd7ec6.mp3\", \"/storage/v1/object/public/pronunciation/v2/handle-aru7-a2dd7ec6.mp3\", \"/storage/v1/object/public/pronunciation/v2/handle-aru8-a2dd7ec6.mp3\", \"/storage/v1/object/public/pronunciation/v2/handle-aru2-a2dd7ec6.mp3\"]}, \"us\": {\"nu\": [\"/storage/