('6ea546a7-50b8-5837-a246-4fd6bc13e76f', 'f22c8c20-af01-5c36-b57d-2e84d1a5e7dd', '55bc2eee-3883-5b91-b7bd-496bb0e9f937', '376dabd1-4d9f-51b9-bf81-c033af9a03a2', 'refuse', '/rɪˈfjuːz/', 'B1', 'verb', 'Không chấp nhận hoặc không làm điều gì đó.', 'to show that you are not willing to do.', 'He refused to answer any questions about the incident.', 'Anh ấy từ chối trả lời bất kỳ câu hỏi nào về vụ việc.', '{\"en\": \"The supplier refused to deliver the goods without full payment.\", \"vi\": \"Nhà cung cấp đã từ chối giao hàng nếu không nhận đủ tiền.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/refuse-ljspeech-106f0aba.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/refuse-cori-106f0aba.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/refuse-9a6569aa.webp', '[\"decline\", \"reject\"]', '[\"accept\"]', '[{\"phrase\": \"refuse an offer\", \"meaning\": \"từ chối lời đề nghị\"}, {\"phrase\": \"refuse to do\", \"meaning\": \"từ chối làm\"}, {\"phrase\": \"refuse payment\", \"meaning\": \"từ chối thanh toán\"}]', '[{\"word\": \"refute\", \"note_vi\": \"refute là bác bỏ, refuse là từ chối\"}]', '[{\"pos\": \"noun\", \"word\": \"refusal\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/refuse-cori-106f0aba.mp3\", \"/storage/v1/object/public/pronunciation/v2/refuse-aru0-106f0aba.mp3\", \"/storage/v1/object/public/pronunciation/v2/refuse-aru5-106f0aba.mp3\", \"/storage/v1/object/public/pronunciation/v2/refuse-aru6-106f0aba.mp3\", \"/storage/v1/object/public/pronunciation/v2/refuse-aru10-106f0aba.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/refuse-aru9-106f0aba.mp3\", \"/storage/v1/object/public/pronunciation/v2/refuse-aru3-106f0aba.mp3\", \"/storage/v1/object/public/pronunciation/v2/refuse-aru7-106f0aba.mp3\", \"/storage/v1/object/public/pronunciation/v2/refuse-aru8-106f0aba.mp3\", \"/storage/v1/object/public/pronunciation/v2/refuse-aru2-106f0aba.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/objec