('73f8aafd-a8df-5c06-ad56-b599c417c037', 'f22c8c20-af01-5c36-b57d-2e84d1a5e7dd', '6c965487-9672-5c93-91d9-6a518b81a343', 'e10e6150-10ee-59cf-8f80-39a6f45d35ff', 'possession', '/pəˈzeʃn/', 'B1', 'noun', 'tài sản, vật sở hữu', 'something that you own or have with you at a particular time.', 'Please keep track of your personal possessions during the trip.', 'Xin hãy trông chừng tài sản cá nhân của bạn trong suốt chuyến đi.', '{\"en\": \"Please make sure you do not leave any personal possession in the meeting room.\", \"vi\": \"Vui lòng đảm bảo bạn không để lại bất kỳ tài sản cá nhân nào trong phòng họp.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/possession-ljspeech-914fb82e.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/possession-cori-914fb82e.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/possession-df8040e4.webp', '[\"belonging\", \"property\", \"asset\"]', NULL, '[{\"phrase\": \"personal possessions\", \"meaning\": \"tài sản cá nhân\"}, {\"phrase\": \"take possession of\", \"meaning\": \"sở hữu, tiếp quản\"}]', '[{\"word\": \"property\", \"note_vi\": \"property thường chỉ bất động sản hoặc tài sản lớn hơn\"}]', '[{\"pos\": \"verb\", \"word\": \"possess\"}, {\"pos\": \"adjective\", \"word\": \"possessive\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/possession-cori-914fb82e.mp3\", \"/storage/v1/object/public/pronunciation/v2/possession-aru0-914fb82e.mp3\", \"/storage/v1/object/public/pronunciation/v2/possession-aru5-914fb82e.mp3\", \"/storage/v1/object/public/pronunciation/v2/possession-aru6-914fb82e.mp3\", \"/storage/v1/object/public/pronunciation/v2/possession-aru10-914fb82e.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/possession-aru9-914fb82e.mp3\", \"/storage/v1/object/public/pronunciation/v2/possession-aru3-914fb82e.mp3\", \"/storage/v1/object/public/pronunciation/v2/possession-aru7-914fb82e.mp3\", \"/storage/v1/object/public/pronunciation/v2/possession-aru8-914