('a601e5fe-dd60-51d3-b1f0-2ee9d0495c5a', 'f22c8c20-af01-5c36-b57d-2e84d1a5e7dd', '868e0ad7-8ba9-53eb-9252-8c0c7f155e86', 'c8fdd44d-f347-53fc-b512-c83e8a88568a', 'promise', '/ˈprɒmɪs/', 'A2', 'verb', 'Cam kết sẽ làm hoặc không làm điều gì đó.', 'to tell someone that you will certainly do or not do something.', 'He promised to help me move my furniture this weekend.', 'Anh ấy đã hứa sẽ giúp tôi chuyển đồ đạc vào cuối tuần này.', '{\"en\": \"The supplier promised to deliver the new office chairs by next Monday morning.\", \"vi\": \"Nhà cung cấp đã hứa sẽ giao các ghế văn phòng mới trước sáng Thứ Hai tuần tới.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/promise-ljspeech-8c2fd844.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/promise-cori-8c2fd844.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/promise-d0c53fad.webp', '[\"guarantee\", \"pledge\", \"vow\"]', NULL, '[{\"phrase\": \"promise to do\", \"meaning\": \"hứa làm gì\"}, {\"phrase\": \"firmly promise\", \"meaning\": \"hứa chắc chắn\"}]', '[{\"word\": \"permit\", \"note_vi\": \"permit là cho phép, promise là hứa\"}]', '[{\"pos\": \"noun\", \"word\": \"promise\"}, {\"pos\": \"adjective\", \"word\": \"promising\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/promise-cori-8c2fd844.mp3\", \"/storage/v1/object/public/pronunciation/v2/promise-aru0-8c2fd844.mp3\", \"/storage/v1/object/public/pronunciation/v2/promise-aru5-8c2fd844.mp3\", \"/storage/v1/object/public/pronunciation/v2/promise-aru6-8c2fd844.mp3\", \"/storage/v1/object/public/pronunciation/v2/promise-aru10-8c2fd844.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/promise-aru9-8c2fd844.mp3\", \"/storage/v1/object/public/pronunciation/v2/promise-aru3-8c2fd844.mp3\", \"/storage/v1/object/public/pronunciation/v2/promise-aru7-8c2fd844.mp3\", \"/storage/v1/object/public/pronunciation/v2/promise-aru8-8c2fd844.mp3\", \"/storage/v1/object/public/pronunciation/v2/promise-aru2-8c2fd