('ec687671-8867-5d9b-87db-4fd095bf547e', 'f22c8c20-af01-5c36-b57d-2e84d1a5e7dd', '8caeb67e-edf2-5e8a-ae61-195b88c50a78', '3dd3a3b6-3c1e-530e-b338-cd56dc24438e', 'especially', '/ɪˈspeʃəli/', 'A2', 'adverb', 'hơn hẳn những cái khác; đặc biệt là.', 'used to emphasize that something is more important or true for a particular person or thing.', 'This vehicle is suited for long journeys, especially in rainy weather conditions.', 'Phương tiện này rất phù hợp cho những chuyến đi xa, đặc biệt là trong điều kiện thời tiết mưa.', '{\"en\": \"The new software is useful for all staff, especially those working in the accounting department.\", \"vi\": \"Phần mềm mới hữu ích cho tất cả nhân viên, đặc biệt là những người làm trong phòng kế toán.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/especially-ljspeech-8284b5c9.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/especially-cori-8284b5c9.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/especially-3a1125b5.webp', '[\"particularly\", \"specifically\"]', NULL, '[{\"phrase\": \"especially important\", \"meaning\": \"đặc biệt quan trọng\"}, {\"phrase\": \"especially true\", \"meaning\": \"đặc biệt đúng\"}]', '[{\"word\": \"specially\", \"note_vi\": \"specially dùng cho mục đích riêng biệt, especially dùng để nhấn mạnh.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/especially-cori-8284b5c9.mp3\", \"/storage/v1/object/public/pronunciation/v2/especially-aru0-8284b5c9.mp3\", \"/storage/v1/object/public/pronunciation/v2/especially-aru5-8284b5c9.mp3\", \"/storage/v1/object/public/pronunciation/v2/especially-aru6-8284b5c9.mp3\", \"/storage/v1/object/public/pronunciation/v2/especially-aru10-8284b5c9.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/especially-aru9-8284b5c9.mp3\", \"/storage/v1/object/public/pronunciation/v2/especially-aru3-8284b5c9.mp3\", \"/storage/v1/object/public/pronunciation/v2/especially-aru7-8284b5c9.mp3\", \"/storage/v1/obj