('0a75538c-33fc-5974-82ee-da5303cbbea6', 'f22c8c20-af01-5c36-b57d-2e84d1a5e7dd', 'adb223f5-560b-5753-87cc-b6208d1ad5e3', 'b35cc101-07ac-5a98-8b4c-9eb3f164d155', 'pilot', '/ˈpaɪlət/', 'A2', 'noun', 'người lái máy bay hoặc tàu vũ trụ', 'A licensed professional qualified to navigate and fly an airplane or helicopter safely.', 'The pilot announced that we would be landing in about twenty minutes.', 'Phi công thông báo rằng chúng ta sẽ hạ cánh trong khoảng hai mươi phút nữa.', '{\"en\": \"The experienced pilot announced the landing time to the passengers.\", \"vi\": \"Phi công dày dạn kinh nghiệm đã thông báo thời gian hạ cánh cho hành khách.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/pilot-ljspeech-eec7121e.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/pilot-cori-eec7121e.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/pilot-69ac3349.webp', '[\"aviator\", \"flyer\"]', NULL, '[{\"phrase\": \"airline pilot\", \"meaning\": \"phi công hàng không\"}, {\"phrase\": \"pilot license\", \"meaning\": \"bằng lái máy bay\"}, {\"phrase\": \"train a pilot\", \"meaning\": \"đào tạo phi công\"}]', '[{\"word\": \"pirate\", \"note_vi\": \"pilot phi công; pirate cướp biển.\"}]', '[{\"pos\": \"verb\", \"word\": \"pilot\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/pilot-cori-eec7121e.mp3\", \"/storage/v1/object/public/pronunciation/v2/pilot-aru0-eec7121e.mp3\", \"/storage/v1/object/public/pronunciation/v2/pilot-aru5-eec7121e.mp3\", \"/storage/v1/object/public/pronunciation/v2/pilot-aru6-eec7121e.mp3\", \"/storage/v1/object/public/pronunciation/v2/pilot-aru10-eec7121e.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/pilot-aru9-eec7121e.mp3\", \"/storage/v1/object/public/pronunciation/v2/pilot-aru3-eec7121e.mp3\", \"/storage/v1/object/public/pronunciation/v2/pilot-aru7-eec7121e.mp3\", \"/storage/v1/object/public/pronunciation/v2/pilot-aru8-eec7121e.mp3\", \"/storage/v1/object/public/pronunciation/