('56266598-8dd2-58f7-bd13-13ee19957080', 'f22c8c20-af01-5c36-b57d-2e84d1a5e7dd', 'bdb26425-e39b-559b-8d54-303aacf0920b', '86fc3c20-8a1e-5d1e-9d63-836c534f6984', 'term', '/tɜːm/', 'A2', 'noun', 'một khoảng thời gian cụ thể, thường trong học kỳ hoặc hợp đồng.', 'one of the periods of time that the school or university year is divided into.', 'Students have to register for the next academic term by Friday.', 'Sinh viên phải đăng ký cho học kỳ tiếp theo trước thứ Sáu.', '{\"en\": \"The contract covers a fixed term of three years for the new office lease.\", \"vi\": \"Hợp đồng bao gồm một thời hạn cố định ba năm cho việc thuê văn phòng mới.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/term-ljspeech-2a4c3b84.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/term-cori-2a4c3b84.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/term-45dcabdc.webp', '[\"period\", \"semester\"]', NULL, '[{\"phrase\": \"academic term\", \"meaning\": \"học kỳ\"}, {\"phrase\": \"midterm exam\", \"meaning\": \"kỳ thi giữa kỳ\"}]', '[{\"word\": \"semester\", \"note_vi\": \"semester thường là kỳ học 6 tháng, term có thể ngắn hơn.\"}]', '[{\"pos\": \"verb\", \"word\": \"terminate\"}, {\"pos\": \"adjective\", \"word\": \"terminal\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/term-cori-2a4c3b84.mp3\", \"/storage/v1/object/public/pronunciation/v2/term-aru0-2a4c3b84.mp3\", \"/storage/v1/object/public/pronunciation/v2/term-aru5-2a4c3b84.mp3\", \"/storage/v1/object/public/pronunciation/v2/term-aru6-2a4c3b84.mp3\", \"/storage/v1/object/public/pronunciation/v2/term-aru10-2a4c3b84.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/term-aru9-2a4c3b84.mp3\", \"/storage/v1/object/public/pronunciation/v2/term-aru3-2a4c3b84.mp3\", \"/storage/v1/object/public/pronunciation/v2/term-aru7-2a4c3b84.mp3\", \"/storage/v1/object/public/pronunciation/v2/term-aru8-2a4c3b84.mp3\", \"/storage/v1/object/public/pronunciation/v2/term-aru2-2a4c