('b79972f2-be46-5e25-a3cd-5b80cdc62343', 'f22c8c20-af01-5c36-b57d-2e84d1a5e7dd', 'cbb21ab6-b3db-5bd1-9ba1-2c0db96c839a', 'd621bca7-b344-5e47-89db-ee89e75bd3d6', 'firm', 'UK: /fɜːm/ | US: /fɜːrm/', 'B1', 'noun', 'công ty, hãng', 'a commercial organization or business entity that provides professional services or products.', 'Our firm is hiring new marketing specialists.', 'Công ty chúng tôi đang tuyển chuyên viên tiếp thị mới.', '{\"en\": \"She was recently hired as a senior consultant by an international accounting firm.\", \"vi\": \"Cô ấy vừa được nhận vào làm cố vấn cao cấp tại một công ty kế toán quốc tế.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/firm-ljspeech-d340949e.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/firm-cori-d340949e.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/firm-49f46465.webp', '[\"company\", \"corporation\", \"enterprise\", \"business\"]', NULL, '[{\"phrase\": \"law firm\", \"meaning\": \"công ty luật\"}, {\"phrase\": \"accounting firm\", \"meaning\": \"công ty kế toán\"}, {\"phrase\": \"consulting firm\", \"meaning\": \"công ty tư vấn\"}]', NULL, '[{\"pos\": \"adjective\", \"word\": \"firm\"}, {\"pos\": \"adverb\", \"word\": \"firmly\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/firm-cori-d340949e.mp3\", \"/storage/v1/object/public/pronunciation/v2/firm-aru0-d340949e.mp3\", \"/storage/v1/object/public/pronunciation/v2/firm-aru5-d340949e.mp3\", \"/storage/v1/object/public/pronunciation/v2/firm-aru6-d340949e.mp3\", \"/storage/v1/object/public/pronunciation/v2/firm-aru10-d340949e.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/firm-aru9-d340949e.mp3\", \"/storage/v1/object/public/pronunciation/v2/firm-aru3-d340949e.mp3\", \"/storage/v1/object/public/pronunciation/v2/firm-aru7-d340949e.mp3\", \"/storage/v1/object/public/pronunciation/v2/firm-aru8-d340949e.mp3\", \"/storage/v1/object/public/pronunciation/v2/firm-aru2-d340949e.mp3\"]}, \"us\": {\"