('627c6886-55c8-5b18-82b5-31736614d1c6', 'f22c8c20-af01-5c36-b57d-2e84d1a5e7dd', 'd4f0c4de-b4a8-5081-a6da-9acf26ae9945', '290d8e0f-12d5-5f19-85f4-b2e75104611c', 'advertise', '/ˈædvətaɪz/', 'B1', 'verb', 'thông báo về sản phẩm/dịch vụ để thu hút khách hàng.', 'to make a product known to the public.', 'The company decided to advertise their new product on social media.', 'Công ty quyết định quảng cáo sản phẩm mới của họ trên mạng xã hội.', '{\"en\": \"We advertise our company services on the local business website.\", \"vi\": \"Chúng tôi quảng cáo dịch vụ công ty trên trang web kinh doanh địa phương.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/advertise-ljspeech-210787a5.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/advertise-cori-210787a5.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/advertise-a02beefb.webp', '[\"promote\", \"publicize\", \"market\"]', '[\"hide\", \"conceal\"]', '[{\"phrase\": \"advertise a product\", \"meaning\": \"quảng cáo sản phẩm\"}, {\"phrase\": \"advertise on tv\", \"meaning\": \"quảng cáo trên tv\"}, {\"phrase\": \"heavily advertise\", \"meaning\": \"quảng cáo rầm rộ\"}]', '[{\"word\": \"advertize\", \"note_vi\": \"viết sai chính tả, đúng là advertise\"}]', '[{\"pos\": \"noun\", \"word\": \"advertisement\"}, {\"pos\": \"adjective\", \"word\": \"advertising\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/advertise-cori-210787a5.mp3\", \"/storage/v1/object/public/pronunciation/v2/advertise-aru0-210787a5.mp3\", \"/storage/v1/object/public/pronunciation/v2/advertise-aru5-210787a5.mp3\", \"/storage/v1/object/public/pronunciation/v2/advertise-aru6-210787a5.mp3\", \"/storage/v1/object/public/pronunciation/v2/advertise-aru10-210787a5.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/advertise-aru9-210787a5.mp3\", \"/storage/v1/object/public/pronunciation/v2/advertise-aru3-210787a5.mp3\", \"/storage/v1/object/public/pronunciation/v2/advertise-aru7-210787a5.m