('16d38494-d796-5a76-9096-be652b86482d', 'f22c8c20-af01-5c36-b57d-2e84d1a5e7dd', 'e85a4f9d-cc85-5052-b792-a0f120d7fbd1', '143573d0-fa40-5023-8dcb-7db752f735ee', 'hall', '/hɔːl/', 'A2', 'noun', 'Lối đi dài trong tòa nhà hoặc sảnh lớn.', 'a building or large room used for public meetings, concerts, or exhibitions.', 'Please wait for me in the main hall while I get my coat.', 'Xin hãy đợi tôi ở sảnh chính trong khi tôi lấy áo khoác.', '{\"en\": \"The press conference will be held in the main exhibition hall on the first floor.\", \"vi\": \"Buổi họp báo sẽ được tổ chức tại sảnh triển lãm chính ở tầng một.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/hall-ljspeech-4b5fdc6e.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/hall-cori-4b5fdc6e.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/hall-c46b2f5d.webp', '[\"corridor\", \"lobby\", \"auditorium\"]', NULL, '[{\"phrase\": \"exhibition hall\", \"meaning\": \"sảnh triển lãm\"}, {\"phrase\": \"conference hall\", \"meaning\": \"phòng hội nghị\"}]', '[{\"word\": \"hole\", \"note_vi\": \"nghĩa là cái hố, phát âm khác nhau ở nguyên âm\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/hall-cori-4b5fdc6e.mp3\", \"/storage/v1/object/public/pronunciation/v2/hall-aru0-4b5fdc6e.mp3\", \"/storage/v1/object/public/pronunciation/v2/hall-aru5-4b5fdc6e.mp3\", \"/storage/v1/object/public/pronunciation/v2/hall-aru6-4b5fdc6e.mp3\", \"/storage/v1/object/public/pronunciation/v2/hall-aru10-4b5fdc6e.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/hall-aru9-4b5fdc6e.mp3\", \"/storage/v1/object/public/pronunciation/v2/hall-aru3-4b5fdc6e.mp3\", \"/storage/v1/object/public/pronunciation/v2/hall-aru7-4b5fdc6e.mp3\", \"/storage/v1/object/public/pronunciation/v2/hall-aru8-4b5fdc6e.mp3\", \"/storage/v1/object/public/pronunciation/v2/hall-aru2-4b5fdc6e.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/hall-ljspeech-4b5fdc6e.mp3\", \"/stora