('5397d00d-8b32-5766-aeee-e644beaef4e7', 'f22c8c20-af01-5c36-b57d-2e84d1a5e7dd', 'e85a4f9d-cc85-5052-b792-a0f120d7fbd1', '143573d0-fa40-5023-8dcb-7db752f735ee', 'sweet', '/swiːt/', 'A1', 'adjective', 'có vị ngọt, dễ chịu', 'having a taste similar to that of sugar or honey.', 'This cake is too sweet for my taste.', 'Chiếc bánh này quá ngọt so với khẩu vị của tôi.', '{\"en\": \"The bakery is famous for its sweet desserts that attract many local customers.\", \"vi\": \"Tiệm bánh nổi tiếng với các món tráng miệng ngọt ngào thu hút nhiều khách hàng địa phương.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/sweet-ljspeech-457774c6.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/sweet-cori-457774c6.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/sweet-74f19aae.webp', '[\"sugary\", \"honeyed\"]', '[\"sour\", \"bitter\", \"salty\"]', '[{\"phrase\": \"sweet taste\", \"meaning\": \"vị ngọt\"}, {\"phrase\": \"sweet tooth\", \"meaning\": \"sở thích ăn đồ ngọt\"}]', '[{\"word\": \"suite\", \"note_vi\": \"suite phát âm giống sweet nhưng nghĩa là dãy phòng\"}]', '[{\"pos\": \"verb\", \"word\": \"sweeten\"}, {\"pos\": \"noun\", \"word\": \"sweetness\"}, {\"pos\": \"adverb\", \"word\": \"sweetly\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/sweet-cori-457774c6.mp3\", \"/storage/v1/object/public/pronunciation/v2/sweet-aru0-457774c6.mp3\", \"/storage/v1/object/public/pronunciation/v2/sweet-aru5-457774c6.mp3\", \"/storage/v1/object/public/pronunciation/v2/sweet-aru6-457774c6.mp3\", \"/storage/v1/object/public/pronunciation/v2/sweet-aru10-457774c6.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/sweet-aru9-457774c6.mp3\", \"/storage/v1/object/public/pronunciation/v2/sweet-aru3-457774c6.mp3\", \"/storage/v1/object/public/pronunciation/v2/sweet-aru7-457774c6.mp3\", \"/storage/v1/object/public/pronunciation/v2/sweet-aru8-457774c6.mp3\", \"/storage/v1/object/public/pronunciation/v2/sweet-aru2-457774c6.