('1c6d7ba7-be37-51bc-a7ca-0580e043a7a4', 'f22c8c20-af01-5c36-b57d-2e84d1a5e7dd', 'f40dd9ed-cb9c-5c6a-a96d-4561ff050ee9', '8d167174-52fb-5f28-8eb8-5e330cbe8321', 'airport', 'UK: /ˈeəpɔːt/ | US: /ˈɛrˌpɔrt/', 'A2', 'noun', 'sân bay', 'a facility with runways and buildings for takeoff, landing, and maintenance of flying vehicles.', 'The airport is busy during holiday seasons.', 'Sân bay tấp nập trong các mùa lễ.', '{\"en\": \"Passengers are advised to arrive at the airport at least two hours before domestic flights.\", \"vi\": \"Hành khách được khuyên nên đến sân bay ít nhất hai giờ trước các chuyến bay nội địa.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/airport-ljspeech-6b5465bf.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/airport-cori-6b5465bf.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/airport-78cc5f9a.webp', '[\"airfield\", \"aerodrome\", \"terminal\"]', NULL, '[{\"phrase\": \"airport terminal\", \"meaning\": \"nhà ga sân bay\"}, {\"phrase\": \"airport security\", \"meaning\": \"an ninh sân bay\"}, {\"phrase\": \"airport shuttle\", \"meaning\": \"xe buýt đưa đón sân bay\"}]', '[{\"word\": \"airplane\", \"note_vi\": \"máy bay (phương tiện), trong khi airport là sân bay (địa điểm)\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/airport-cori-6b5465bf.mp3\", \"/storage/v1/object/public/pronunciation/v2/airport-aru0-6b5465bf.mp3\", \"/storage/v1/object/public/pronunciation/v2/airport-aru5-6b5465bf.mp3\", \"/storage/v1/object/public/pronunciation/v2/airport-aru6-6b5465bf.mp3\", \"/storage/v1/object/public/pronunciation/v2/airport-aru10-6b5465bf.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/airport-aru9-6b5465bf.mp3\", \"/storage/v1/object/public/pronunciation/v2/airport-aru3-6b5465bf.mp3\", \"/storage/v1/object/public/pronunciation/v2/airport-aru7-6b5465bf.mp3\", \"/storage/v1/object/public/pronunciation/v2/airport-aru8-6b5465bf.mp3\", \"/storage/v1/object/public/p