('7aaa4fa0-64f9-513e-8edb-358ba6a9e634', 'fa0ef8f0-6a34-5cb5-b8c8-5551c70b5086', '06a38396-1063-5155-b665-f0594ae2ae39', '21411bc9-f78c-5941-852b-1b34486bd977', 'pour', '/pɔː(r)/', 'A2', 'verb', 'Đổ chất lỏng ra khỏi vật chứa.', 'to cause a liquid to flow from one container to another.', 'The barista will pour hot milk carefully into the coffee cup.', 'Nhân viên pha chế sẽ rót sữa nóng cẩn thận vào tách cà phê.', '{\"en\": \"The waiter will pour coffee for the guests during the business lunch meeting.\", \"vi\": \"Người phục vụ sẽ rót cà phê cho khách trong buổi tiệc trưa kinh doanh.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/pour-ljspeech-03c988f5.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/pour-cori-03c988f5.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/pour-d4195c32.webp', '[\"tip\", \"decant\"]', NULL, '[{\"phrase\": \"pour a drink\", \"meaning\": \"rót một thức uống\"}, {\"phrase\": \"pour out\", \"meaning\": \"đổ ra ngoài\"}]', '[{\"word\": \"pout\", \"note_vi\": \"pout là chu môi, không phải đổ chất lỏng\"}, {\"word\": \"poor\", \"note_vi\": \"poor nghĩa là nghèo, phát âm gần\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/pour-cori-03c988f5.mp3\", \"/storage/v1/object/public/pronunciation/v2/pour-aru0-03c988f5.mp3\", \"/storage/v1/object/public/pronunciation/v2/pour-aru5-03c988f5.mp3\", \"/storage/v1/object/public/pronunciation/v2/pour-aru6-03c988f5.mp3\", \"/storage/v1/object/public/pronunciation/v2/pour-aru10-03c988f5.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/pour-aru9-03c988f5.mp3\", \"/storage/v1/object/public/pronunciation/v2/pour-aru3-03c988f5.mp3\", \"/storage/v1/object/public/pronunciation/v2/pour-aru7-03c988f5.mp3\", \"/storage/v1/object/public/pronunciation/v2/pour-aru8-03c988f5.mp3\", \"/storage/v1/object/public/pronunciation/v2/pour-aru2-03c988f5.mp3\"]}, \"us\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/pour-ljspeech-03c98