('0451df1e-daaf-5a10-9290-df7fd0838938', 'fa0ef8f0-6a34-5cb5-b8c8-5551c70b5086', '2c8fb2ac-3215-57de-858b-a1522ce492c1', '7c72d5cc-a675-596c-b902-4064bf68f403', 'career', 'UK: /kəˈrɪə/ | US: /kəˈrɪr/', 'B1', 'noun', 'sự nghiệp', 'an occupation or profession undertaken for a significant period of a person\'s life', 'She pursued a successful career in marketing.', 'Cô ấy theo đuổi một sự nghiệp thành công trong lĩnh vực marketing.', '{\"en\": \"The seminar aims to help junior employees develop clear career advancement plans.\", \"vi\": \"Hội thảo nhằm mục đích giúp các nhân viên cấp thấp xây dựng kế hoạch thăng tiến sự nghiệp rõ ràng.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/career-ljspeech-25f6f053.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/career-cori-25f6f053.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/career-fc179a0e.webp', '[\"profession\", \"occupation\", \"vocation\"]', NULL, '[{\"phrase\": \"career path\", \"meaning\": \"con đường sự nghiệp\"}, {\"phrase\": \"career advancement\", \"meaning\": \"sự thăng tiến trong sự nghiệp\"}, {\"phrase\": \"career opportunities\", \"meaning\": \"cơ hội nghề nghiệp\"}]', '[{\"word\": \"carrier\", \"note_vi\": \"Carrier nghĩa là hãng vận tải hoặc người vận chuyển, phát âm và nghĩa đều khác với career.\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/career-cori-25f6f053.mp3\", \"/storage/v1/object/public/pronunciation/v2/career-aru0-25f6f053.mp3\", \"/storage/v1/object/public/pronunciation/v2/career-aru5-25f6f053.mp3\", \"/storage/v1/object/public/pronunciation/v2/career-aru6-25f6f053.mp3\", \"/storage/v1/object/public/pronunciation/v2/career-aru10-25f6f053.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/career-aru9-25f6f053.mp3\", \"/storage/v1/object/public/pronunciation/v2/career-aru3-25f6f053.mp3\", \"/storage/v1/object/public/pronunciation/v2/career-aru7-25f6f053.mp3\", \"/storage/v1/object/public/pronunciation/v