('bd284998-4acb-51e0-bf7e-ff1c2fe8dff4', 'fa0ef8f0-6a34-5cb5-b8c8-5551c70b5086', '447ded16-011c-55a0-ba6a-e416e06f015f', 'f3fbaf4b-55eb-5303-9a41-4e17ea8b2dc9', 'contact', '/ˈkɒntækt/', 'A2', 'noun', 'sự liên hệ hoặc giao tiếp với ai đó.', 'the act of communicating or meeting with another person.', 'You can contact the customer service department directly by calling this toll-free number.', 'Bạn có thể liên hệ trực tiếp với bộ phận chăm sóc khách hàng bằng cách gọi số miễn phí này.', '{\"en\": \"Our sales agent will make contact with the client next Monday.\", \"vi\": \"Nhân viên bán hàng của chúng tôi sẽ liên hệ với khách hàng vào thứ Hai tới.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/contact-ljspeech-1a73af9e.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/contact-cori-1a73af9e.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/contact-44e9a16b.webp', '[\"communication\", \"connection\", \"touch\"]', '[\"isolation\"]', '[{\"phrase\": \"make contact\", \"meaning\": \"liên hệ\"}, {\"phrase\": \"keep in contact\", \"meaning\": \"giữ liên lạc\"}, {\"phrase\": \"close contact\", \"meaning\": \"tiếp xúc gần\"}]', '[{\"word\": \"contract\", \"note_vi\": \"contact là liên hệ, contract là hợp đồng.\"}]', '[{\"pos\": \"verb\", \"word\": \"contact\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/contact-cori-1a73af9e.mp3\", \"/storage/v1/object/public/pronunciation/v2/contact-aru0-1a73af9e.mp3\", \"/storage/v1/object/public/pronunciation/v2/contact-aru5-1a73af9e.mp3\", \"/storage/v1/object/public/pronunciation/v2/contact-aru6-1a73af9e.mp3\", \"/storage/v1/object/public/pronunciation/v2/contact-aru10-1a73af9e.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/contact-aru9-1a73af9e.mp3\", \"/storage/v1/object/public/pronunciation/v2/contact-aru3-1a73af9e.mp3\", \"/storage/v1/object/public/pronunciation/v2/contact-aru7-1a73af9e.mp3\", \"/storage/v1/object/public/pronunciation/v2/contact-aru8