('6e9ed8d7-09a2-5405-a802-2e6fb12a2a0a', 'fa0ef8f0-6a34-5cb5-b8c8-5551c70b5086', '4949f93f-52d4-5176-ba7c-af70f377204c', 'af935662-d356-59d7-9198-3e6f19f5a668', 'audience', 'UK: /ˈɔːdiəns/ | US: /ˈɔdiəns/', 'B1', 'noun', 'khán giả', 'a group of assembled listeners or viewers gathered to watch or listen to a performance.', 'The audience applauded loudly after the speech.', 'Khán giả vỗ tay nồng nhiệt sau bài phát biểu.', '{\"en\": \"The speaker kept the audience engaged throughout the entire two-hour presentation.\", \"vi\": \"Diễn giả đã giữ sự chú ý của khán giả xuyên suốt bài thuyết trình kéo dài hai giờ.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/audience-ljspeech-a4930bb8.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/audience-cori-a4930bb8.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/audience-7a6cc976.webp', '[\"listeners\", \"viewers\", \"spectators\", \"assembly\"]', NULL, '[{\"phrase\": \"target audience\", \"meaning\": \"khán giả/đối tượng mục tiêu\"}, {\"phrase\": \"audience reaction\", \"meaning\": \"phản ứng của khán giả\"}]', '[{\"word\": \"spectator\", \"note_vi\": \"spectator thường dùng để chỉ người xem các sự kiện thể thao ngoài trời\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/audience-cori-a4930bb8.mp3\", \"/storage/v1/object/public/pronunciation/v2/audience-aru0-a4930bb8.mp3\", \"/storage/v1/object/public/pronunciation/v2/audience-aru5-a4930bb8.mp3\", \"/storage/v1/object/public/pronunciation/v2/audience-aru6-a4930bb8.mp3\", \"/storage/v1/object/public/pronunciation/v2/audience-aru10-a4930bb8.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/audience-aru9-a4930bb8.mp3\", \"/storage/v1/object/public/pronunciation/v2/audience-aru3-a4930bb8.mp3\", \"/storage/v1/object/public/pronunciation/v2/audience-aru7-a4930bb8.mp3\", \"/storage/v1/object/public/pronunciation/v2/audience-aru8-a4930bb8.mp3\", \"/storage/v1/object/public/pronunciation/v2/audienc