('0b4d1658-5035-5395-99df-69a2bd2276ca', 'fa0ef8f0-6a34-5cb5-b8c8-5551c70b5086', '55787b4f-732a-50ea-9427-0a64d4080f05', '1323f490-cf13-543b-a8cf-e92fe1f09e93', 'applicant', 'UK: /ˈæplɪkənt/ | US: /ˈæplɪkənt/', 'B1', 'noun', 'người ứng tuyển', 'A person who formally requests or seeks a job, position, or role.', 'The applicant must have at least five years of experience.', 'Người ứng tuyển phải có ít nhất năm năm kinh nghiệm.', '{\"en\": \"Qualified applicants will be invited for an interview next Monday.\", \"vi\": \"Những ứng viên đủ điều kiện sẽ được mời đến phỏng vấn vào thứ Hai tuần tới.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/applicant-ljspeech-f3a51c09.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/applicant-cori-f3a51c09.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/applicant-00a1f354.webp', '[\"candidate\", \"job seeker\", \"contender\"]', NULL, '[{\"phrase\": \"job applicant\", \"meaning\": \"người ứng tuyển công việc\"}, {\"phrase\": \"successful applicant\", \"meaning\": \"ứng viên trúng tuyển\"}]', '[{\"word\": \"application\", \"note_vi\": \"Application là tờ đơn/ứng dụng, còn applicant là người nộp đơn.\"}]', '[{\"pos\": \"verb\", \"word\": \"apply\"}, {\"pos\": \"noun\", \"word\": \"application\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/applicant-cori-f3a51c09.mp3\", \"/storage/v1/object/public/pronunciation/v2/applicant-aru0-f3a51c09.mp3\", \"/storage/v1/object/public/pronunciation/v2/applicant-aru5-f3a51c09.mp3\", \"/storage/v1/object/public/pronunciation/v2/applicant-aru6-f3a51c09.mp3\", \"/storage/v1/object/public/pronunciation/v2/applicant-aru10-f3a51c09.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/applicant-aru9-f3a51c09.mp3\", \"/storage/v1/object/public/pronunciation/v2/applicant-aru3-f3a51c09.mp3\", \"/storage/v1/object/public/pronunciation/v2/applicant-aru7-f3a51c09.mp3\", \"/storage/v1/object/public/pronunciation/v2/applicant-aru8-f3a