('1fcd99c6-2a55-5df6-94b5-8fc4531af34c', 'fa0ef8f0-6a34-5cb5-b8c8-5551c70b5086', '929e2c7d-a4f3-52a8-9351-3859123a820f', '6afa9c47-dcaf-5478-ba04-a80c39feade6', 'attach', '/əˈtætʃ/', 'B1', 'verb', 'Gắn hoặc nối một vật vào vật khác.', 'to join or fasten one item to another thing firmly.', 'Do not forget to attach the signed contract before sending the email response.', 'Đừng quên đính kèm hợp đồng đã ký trước khi gửi thư phản hồi.', '{\"en\": \"Please attach your updated resume and cover letter when submitting the job application.\", \"vi\": \"Vui lòng đính kèm sơ yếu lý lịch cập nhật và thư xin việc khi nộp hồ sơ ứng tuyển.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/attach-ljspeech-13ce071f.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/attach-cori-13ce071f.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/attach-6a616934.webp', '[\"append\", \"connect\", \"fasten\"]', '[\"detach\", \"disconnect\"]', '[{\"phrase\": \"attach a file\", \"meaning\": \"đính kèm tệp\"}, {\"phrase\": \"attach to\", \"meaning\": \"gắn vào hoặc đính kèm vào\"}, {\"phrase\": \"attached document\", \"meaning\": \"tài liệu được đính kèm\"}]', '[{\"word\": \"attack\", \"note_vi\": \"attack nghĩa là tấn công, khác biệt hoàn toàn với attach (đính kèm).\"}]', '[{\"pos\": \"noun\", \"word\": \"attachment\"}, {\"pos\": \"adjective\", \"word\": \"attached\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/attach-cori-13ce071f.mp3\", \"/storage/v1/object/public/pronunciation/v2/attach-aru0-13ce071f.mp3\", \"/storage/v1/object/public/pronunciation/v2/attach-aru5-13ce071f.mp3\", \"/storage/v1/object/public/pronunciation/v2/attach-aru6-13ce071f.mp3\", \"/storage/v1/object/public/pronunciation/v2/attach-aru10-13ce071f.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/attach-aru9-13ce071f.mp3\", \"/storage/v1/object/public/pronunciation/v2/attach-aru3-13ce071f.mp3\", \"/storage/v1/object/public/pronunciation/v2/attach-