('32242db6-4863-5f6b-9915-60c1837ebedc', 'fa0ef8f0-6a34-5cb5-b8c8-5551c70b5086', 'a4dd6a66-9b37-50ee-b0a4-6bcba96aa151', '100dab08-885e-51ee-9ab5-b17b6611ad13', 'badge', 'UK: /bædʒ/ | US: /bædʒ/', 'B1', 'noun', 'huy hiệu, thẻ', 'a small item or card worn on clothing to indicate identity, position, or official membership', 'Please wear your identification badge at all times.', 'Vui lòng đeo thẻ nhận dạng của bạn mọi lúc.', '{\"en\": \"All employees must scan their identification badge at the turnstile to enter the building.\", \"vi\": \"Tất cả nhân viên phải quét thẻ định danh của họ tại cổng xoay để vào tòa nhà.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/badge-ljspeech-adac3846.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/badge-cori-adac3846.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/badge-8ef8c7a7.webp', '[\"tag\", \"pass\", \"ID card\", \"emblem\"]', NULL, '[{\"phrase\": \"security badge\", \"meaning\": \"thẻ an ninh\"}, {\"phrase\": \"name badge\", \"meaning\": \"thẻ tên\"}, {\"phrase\": \"badge reader\", \"meaning\": \"máy đọc thẻ\"}]', '[{\"word\": \"barge\", \"note_vi\": \"Barge nghĩa là xà sà/thuyền đáy bằng, khác với badge (thẻ/huy hiệu).\"}]', NULL, '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/badge-cori-adac3846.mp3\", \"/storage/v1/object/public/pronunciation/v2/badge-aru0-adac3846.mp3\", \"/storage/v1/object/public/pronunciation/v2/badge-aru5-adac3846.mp3\", \"/storage/v1/object/public/pronunciation/v2/badge-aru6-adac3846.mp3\", \"/storage/v1/object/public/pronunciation/v2/badge-aru10-adac3846.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/badge-aru9-adac3846.mp3\", \"/storage/v1/object/public/pronunciation/v2/badge-aru3-adac3846.mp3\", \"/storage/v1/object/public/pronunciation/v2/badge-aru7-adac3846.mp3\", \"/storage/v1/object/public/pronunciation/v2/badge-aru8-adac3846.mp3\", \"/storage/v1/object/public/pronunciation/v2/badge-aru2-adac3846.mp3\"]}, \"us\