('6a99e6a6-216f-5bb8-8347-bd706d3f1caf', 'fa0ef8f0-6a34-5cb5-b8c8-5551c70b5086', 'a4dd6a66-9b37-50ee-b0a4-6bcba96aa151', '100dab08-885e-51ee-9ab5-b17b6611ad13', 'allow', 'UK: /əˈlaʊ/ | US: /əˈlaʊ/', 'B1', 'verb', 'cho phép', 'to give permission or permit someone to do something without restriction or prohibition.', 'Employees are not allowed to bring pets to the office.', 'Nhân viên không được phép mang thú cưng đến văn phòng.', '{\"en\": \"The new software application allows employees to access client records securely from home.\", \"vi\": \"Ứng dụng phần mềm mới cho phép nhân viên truy cập hồ sơ khách hàng một cách an toàn từ nhà.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/allow-ljspeech-6452e7c5.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/allow-cori-6452e7c5.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/allow-768a5175.webp', '[\"permit\", \"enable\", \"authorize\"]', '[\"prohibit\", \"forbid\", \"ban\"]', '[{\"phrase\": \"allow access to\", \"meaning\": \"cho phép truy cập vào\"}, {\"phrase\": \"allow time for\", \"meaning\": \"dành thời gian cho\"}]', '[{\"word\": \"allot\", \"note_vi\": \"phân bổ/chia phần, không dùng theo cấu trúc allot somebody to do\"}]', '[{\"pos\": \"noun\", \"word\": \"allowance\"}, {\"pos\": \"adjective\", \"word\": \"allowable\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/allow-cori-6452e7c5.mp3\", \"/storage/v1/object/public/pronunciation/v2/allow-aru0-6452e7c5.mp3\", \"/storage/v1/object/public/pronunciation/v2/allow-aru5-6452e7c5.mp3\", \"/storage/v1/object/public/pronunciation/v2/allow-aru6-6452e7c5.mp3\", \"/storage/v1/object/public/pronunciation/v2/allow-aru10-6452e7c5.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/allow-aru9-6452e7c5.mp3\", \"/storage/v1/object/public/pronunciation/v2/allow-aru3-6452e7c5.mp3\", \"/storage/v1/object/public/pronunciation/v2/allow-aru7-6452e7c5.mp3\", \"/storage/v1/object/public/pronunciation/v2/al