('ae5d6fdf-5dcc-5759-9f24-bd5b704e1c30', 'fa0ef8f0-6a34-5cb5-b8c8-5551c70b5086', 'ac09ba7c-ef8c-556a-8ca6-e044064a6a19', 'b9588537-dac3-52d3-94fd-b10fc6e1b708', 'command', 'UK: /kəˈmɑːnd/ | US: /kəˈmænd/', 'B1', 'noun', 'lệnh, chỉ dẫn', 'an instruction given by a person or a computer program to perform a specific action', 'The software responds to voice commands.', 'Phần mềm phản hồi các lệnh bằng giọng nói.', '{\"en\": \"The system will execute the updated code as soon as you press the command key.\", \"vi\": \"Hệ thống sẽ thực thi mã cập nhật ngay khi bạn nhấn phím lệnh.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/command-ljspeech-1925f793.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/command-cori-1925f793.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/command-bdf46780.webp', '[\"order\", \"instruction\", \"directive\"]', NULL, '[{\"phrase\": \"have a good command of\", \"meaning\": \"thông thạo, sử dụng tốt (kỹ năng/ngôn ngữ)\"}, {\"phrase\": \"command line\", \"meaning\": \"dòng lệnh hệ thống\"}]', '[{\"word\": \"commend\", \"note_vi\": \"commend (v) nghĩa là khen ngợi, còn command (n/v) là ra lệnh hoặc sự thông thạo.\"}]', '[{\"pos\": \"verb\", \"word\": \"command\"}, {\"pos\": \"adjective\", \"word\": \"commanding\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/command-cori-1925f793.mp3\", \"/storage/v1/object/public/pronunciation/v2/command-aru0-1925f793.mp3\", \"/storage/v1/object/public/pronunciation/v2/command-aru5-1925f793.mp3\", \"/storage/v1/object/public/pronunciation/v2/command-aru6-1925f793.mp3\", \"/storage/v1/object/public/pronunciation/v2/command-aru10-1925f793.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/command-aru9-1925f793.mp3\", \"/storage/v1/object/public/pronunciation/v2/command-aru3-1925f793.mp3\", \"/storage/v1/object/public/pronunciation/v2/command-aru7-1925f793.mp3\", \"/storage/v1/object/public/pronunciation/v2/command-aru8-1925f793.mp3\"