('bbe32d2c-cbc4-5e41-a859-ba954b27ee09', 'fa0ef8f0-6a34-5cb5-b8c8-5551c70b5086', 'ac09ba7c-ef8c-556a-8ca6-e044064a6a19', 'b9588537-dac3-52d3-94fd-b10fc6e1b708', 'equipment', 'UK: /ɪˈkwɪpmənt/ | US: /ɪˈkwɪpmənt/', 'B1', 'noun', 'thiết bị', 'The necessary tools, machinery, or items needed for a particular activity or purpose.', 'All safety equipment must be checked daily.', 'Tất cả thiết bị an toàn phải được kiểm tra hàng ngày.', '{\"en\": \"All office equipment must be turned off before leaving the building.\", \"vi\": \"Tất cả thiết bị văn phòng phải được tắt trước khi rời khỏi tòa nhà.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/equipment-ljspeech-bedcc40e.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/equipment-cori-bedcc40e.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/equipment-c90fd6b2.webp', '[\"machinery\", \"gear\", \"apparatus\"]', NULL, '[{\"phrase\": \"office equipment\", \"meaning\": \"thiết bị văn phòng\"}, {\"phrase\": \"heavy equipment\", \"meaning\": \"thiết bị hạng nặng/máy móc lớn\"}]', '[{\"word\": \"device\", \"note_vi\": \"\'Device\' là danh từ đếm được (a device / devices), còn \'equipment\' là danh từ không đếm được.\"}]', '[{\"pos\": \"verb\", \"word\": \"equip\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/equipment-cori-bedcc40e.mp3\", \"/storage/v1/object/public/pronunciation/v2/equipment-aru0-bedcc40e.mp3\", \"/storage/v1/object/public/pronunciation/v2/equipment-aru5-bedcc40e.mp3\", \"/storage/v1/object/public/pronunciation/v2/equipment-aru6-bedcc40e.mp3\", \"/storage/v1/object/public/pronunciation/v2/equipment-aru10-bedcc40e.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/equipment-aru9-bedcc40e.mp3\", \"/storage/v1/object/public/pronunciation/v2/equipment-aru3-bedcc40e.mp3\", \"/storage/v1/object/public/pronunciation/v2/equipment-aru7-bedcc40e.mp3\", \"/storage/v1/object/public/pronunciation/v2/equipment-aru8-bedcc40e.mp3\", \"/storage/v1/ob