INSERT INTO system_vocabulary_words (id, set_id, topic_id, part_id, word, ipa, cefr, part_of_speech, meaning_vi, definition_en, example_en, example_vi, example_toeic, audio_us, audio_uk, image_url, synonyms, antonyms, phrases, confusables, word_family, audio_voices, note_vi, toeic_topic, difficulty_level, order_index) VALUES
('2a0ba361-0bbe-50ee-ad08-1dc2165a15a9', 'fa0ef8f0-6a34-5cb5-b8c8-5551c70b5086', 'ac09ba7c-ef8c-556a-8ca6-e044064a6a19', 'b9588537-dac3-52d3-94fd-b10fc6e1b708', 'financial', '/faɪˈnænʃl/', 'B1', 'adjective', 'Liên quan đến tiền bạc hoặc việc quản lý tiền bạc.', 'connected with money, funds, or the management of wealth.', 'She sought advice from a financial expert about her investments.', 'Cô ấy đã tìm lời khuyên từ một chuyên gia tài chính về các khoản đầu tư của mình.', '{\"en\": \"The company reported strong financial results to its shareholders this quarter.\", \"vi\": \"Công ty đã báo cáo kết quả tài chính khả quan cho cổ đông trong quý này.\"}', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/financial-ljspeech-43d49914.mp3', 'https://byetoeic.com/storage/v1/object/public/pronunciation/v2/financial-cori-43d49914.mp3', 'https://cdn.byetoeic.com/vocabulary-images/words/financial-54c47a22.webp', '[\"monetary\", \"fiscal\"]', NULL, '[{\"phrase\": \"financial report\", \"meaning\": \"báo cáo tài chính\"}, {\"phrase\": \"financial support\", \"meaning\": \"hỗ trợ tài chính\"}, {\"phrase\": \"financial year\", \"meaning\": \"năm tài chính\"}]', '[{\"word\": \"financing\", \"note_vi\": \"financing là việc tài trợ, financial là thuộc về tiền\"}]', '[{\"pos\": \"noun\", \"word\": \"finance\"}, {\"pos\": \"adverb\", \"word\": \"financially\"}]', '{\"uk\": {\"nu\": [\"/storage/v1/object/public/pronunciation/v2/financial-cori-43d49914.mp3\", \"/storage/v1/object/public/pronunciation/v2/financial-aru0-43d49914.mp3\", \"/storage/v1/object/public/pronunciation/v2/financial-aru5-43d49914.mp3\", \"/storage/v1/object/public/pronunciation/v2/financial-aru6-43d49914.mp3\", \"/storage/v1/object/public/pronunciation/v2/financial-aru10-43d49914.mp3\"], \"nam\": [\"/storage/v1/object/public/pronunciation/v2/financial-aru9-43d49914.mp3\", \"/storage/v1/object/public/pronunciation/v2/financial-aru3-43d49914.mp3\", \"/storage/v1/object/public/pronunciation/v2/financial-aru